#include <bits/stdc++.h>
using namespace std;

const int MAX = 1e5;
bool f[MAX + 1];

int it = 0;
vector<int> G[MAX];

void get(int size, int v) {
	if (size == 1) return;
	--size;
	while (size >= 1) {
		int ns = -1;
		for (int i = size; i >= 1; i--) {
			if (f[i]) {
				ns = i;
				break;
			}
		}
		assert(ns != -1);
		if (ns >= 1) {
			int t1 = it++;
			G[v].push_back(t1);
			G[t1].push_back(v);
			get(ns, t1);
			size -= ns;
		}
	}
}

int main()
{
	string s;
	cin >> s;
	int n = s.size();
	if (s.front() != '1' || s.back() == '1') {
		cout << -1 << endl;
		return 0;
	}
	f[0] = true;
	for (int i = 1; i < n; i++) {
		if (s[i - 1] == '1') f[i] = true;
		if (s[i - 1] != s[n - i - 1]) {
			cout << -1 << endl;
			return 0;
		}
	}
	get(n, it++);
	assert(it == n);
	for (int i = 0; i < n; i++) {
		for (auto to : G[i]) if (to > i) {
			cout << i + 1 << ' ' << to + 1 << endl;
		}
	}
	return 0;
}

