        adj[i].clear();

    for(auto xy : edges) {
        int x = xy.first;
        int y = xy.second;
        adj[x].push_back(y);
        adj[y].push_back(x);
    }

    string S(n,'0');

    for(auto xy : edges) {
        int sz1 = dfs(xy.first,xy.second);
        int sz2 = dfs(xy.second,xy.first);
        S[sz1-1]=S[sz2-1]='1';
    }
    return S;

}


