const int MAXN = (int)1e5 + 7;
vector<int> G[MAXN];
int n, a[MAXN], b[MAXN], dp[MAXN];
void fail() {
	cout << "-1\n";
	exit(0);
}
void dfs(int v, int prv) {
	dp[v] = 1;
	for(auto& u: G[v]) if(u != prv) {
		dfs(u, v);
		dp[v] += dp[u];
	}
	if(prv != NIL) {
		b[dp[v]] = 1;
		b[n - dp[v]] = 1;
	}
}
void solve() {
	{
		auto S = fetch<string>();
		n = len(S);
		for(int i = 1; i <= n; ++i) a[i] = S[i - 1] - '0';
	}
	vector<int> szs = {n};
	for(int i = 1; i <= n; ++i) if(a[i]) szs.emplace_back(min(i, n - i));
	sort(szs.begin(), szs.end());
	szs.erase(unique(szs.begin(), szs.end()), szs.end());
	DBG(szs);
	int root = NIL, last = 0, curSz = 0;
	for(int i = 0; i < len(szs); ++i) {
		int nRoot = last++;
		if(root != NIL) G[nRoot].emplace_back(root);
		root = nRoot;
		++curSz;
		if(curSz > szs[i]) fail();
		while(curSz != szs[i]) {
			int nLeaf = last++;
			G[root].emplace_back(nLeaf);
			++curSz;
		}
	}
