set<int> st;

void dfs(int x, int siz)
{
	int rt = x;
	siz--; x++;
	while(1)
	{
		set<int>::iterator it = st.lower_bound(siz); 
		if(st.size() == 0 || (it == st.begin() && (*it) != siz)) break;
		if((*it) != siz) --it;
		u[++tot] = rt; v[tot] = x;
		int new_rt = x;
		x += (*it); siz -= (*it);
		st.erase(it);
		dfs(new_rt, (*it));
	}
	while(siz) u[++tot] = rt, v[tot] = x, x++, siz--;
}
