//計算
void calc()
{
	// rightest one find
	int nodes = s.size() - 1;
	vector<pair<int, int>> edges;
	edges.reserve(s.size() - 1);
	while (nodes >= 0 && s[nodes] == '0')nodes--;
	nodes++;
	if (nodes == 0 || s.back() == '1') {
		cout << -1 << endl;
		return;
	}
	REP(i, nodes - 1) {
		edges.push_back({ i + 1,i + 2 });
	}

	// zero find
	vector<int> zeros;
	zeros.reserve(s.size() - 1);
	REP(i, nodes)if (s[i] == '0')zeros.push_back(i + 1);

	// add more node
	int l = 0;
	int r = zeros.size() - 1;
	while (l<=r) {
		if (l==r) {
			int now = zeros[l];
			if (now == nodes + 1 - now) {
				edges.push_back({ now,edges.size() + 2 });
			}
			else {
				cout << -1 << endl;
				return;
			}
		}
		else {
			int nowl = zeros[l];
			int nowr = zeros[r];
			if (nodes + 1 - nowl == nowr) {
				edges.push_back({ nowl,edges.size() + 2 });
			}
			else {
				cout << -1 << endl;
				return;
			}
		}
		l++;
		r--;
	}

	//exception
	if (edges.size() > s.size() - 1) {
		cout << -1 << endl;
		return;
	}

	//rest
	while (edges.size() < s.size() - 1)edges.push_back({ edges.size() + 2,2 });

	//output
	for (auto p : edges)cout << p.first << " " << p.second << endl;
}


