    string s; cin >> s;
    int N = s.length();

    bool ok = true;
    if(s[0] == '0' or s[N-1] == '1') ok = false;
    for(int i=0; i<N-1; i++) {
        int A = i, B = N-i-2;
        if(((s[A] - '0') ^ (s[B] - '0')) == 1) ok = false;
    }

    if(ok == false) {
        cout << -1 << endl;
    }
    else {
        int cur = 0, last = -1;
        for(int i=0; i<N; i++) {
            cur = max(cur, i);
            while(cur < N and s[cur] == '0') cur++;

            if(s[i] == '1') {
                if(last >= 0) printf("%lld %lld\n", last+1, i+1);
                last = i;
            }
            else {
                if(cur == N) cur = last;
                printf("%lld %lld\n", i+1, cur+1);
            }
        }
    }
    return 0;
}

