vector<P> ans;

bool solve(){
	if(!flg[1]) return false;
	if(flg[N]) return false;
	for(int i = 1; i < N; ++i){
		if(flg[i] != flg[N - i]) return false;
	}
	flg[N] = true;
	vector<int> major;
	queue<int> minor;
	for(int i = 1; i <= N; ++i){
		if(flg[i]) major.push_back(i);
		else minor.push(i);
	}
	for(int i = 0; i + 1 < major.size(); ++i){
		ans.push_back(P(major[i], major[i + 1]));
		int d = major[i + 1] - major[i];
		for(int j = 0; j < d - 1; ++j){
			int v = minor.front();
			minor.pop();
			ans.push_back(P(major[i + 1], v));
		}
	}
	return true;
}

