int node;

string S;
vector<int> G[100005];

void solve(int root, int pos)
{
    if(pos < 0)
        return;

    if(pos == 0)
    {
        while(node < S.size() + 1) {
            node++;
            G[root].push_back(node);
        }
        return;
    }

    int indx = pos - 1;

    while(S[indx] == '0')
        indx--;

    while(S.size() + 1 - node > indx + 1)
    {
        node++;
        G[root].push_back(node);
    }

    node++;
    G[root].push_back(node);
    solve(node, indx);
}

