    {
        if(S[i] != S[j])
        {
            cout << -1 << "\n";
            return 0;
        }
    }

    node = 1;
    solve(1, S.size()-1);

    for(int i=1; i<=node; i++)
        for(auto x : G[i])
            cout << i << " " << x << "\n";

    return 0;
}

