    printf("-1\n");
    return 0;
  }
  ll now1 = 1, now2 = n, counter = 0;
  bool flag = false;
  for (ll i = 1; i < n/2; i++) {
    //printf("%d, %d, %d, %d\n", counter, maxC, i, n/2-1);
    if (maxC == 1 || (counter == maxC - 1 && i != n/2 - 1)) {
      printf("%lld %lld\n", now1, i + 1);
      printf("%lld %lld\n", now2, i + 1);
      printf("%lld %lld\n", i + 1, n - i);
      now1 = now2 = i + 1, flag = true;
      continue;
    }
    printf("%lld %lld\n", now1, i + 1);
    printf("%lld %lld\n", now2, n - i);
    if (!flag && s[i] == '1') now1++, now2--, counter++;
  }
