			sz+=2;
			while(sz+1<n-1&&s[sz+1]=='0')sz++,ADD(pos,++tot);
			ADD(pos,++tot);
			pos=tot;sz++;
		}
	}
	while(sz<n)sz++,ADD(pos,++tot);
	rep(i,1,cnt)printf("%d %d\n",u[i],v[i]);
}

