int newV() {
    return counter++;
}

void construct(int sz, int root, deque<int> vs) {

    int A = sz - vs.front();
    int B = vs.front();
    int x = newV();
    output(root, x);
    for (int i = 0; i < B - 1; i++) {
        output(x, newV());
    }
    vs.pop_front();
    if (vs.size() > 0) {
        construct(A, x, vs);
    } else {
        for (int i = 0; i < A - 1; i++) {
            output(x, newV());
        }
    }
};


