inline bool ok(string& s) {
    li n = sz(s);
    if (s[0] == '0') {
        return false;
    }
    if (s[n - 1] == '1') {
        return false;
    }
    rep(i, (n - 1) / 2) {
        if (s[i] != s[n - 2 - i]) {
            return false;
        }
    }
    return true;
}

int main() {
    string s;
    cin >> s;
    li n = sz(s);
    if (!ok(s)) {
        puts("-1");
        return 0;
    }
    if (n == 2) {
        puts("1 2");
        return 0;
    }

    li largest_tree = 0;
    rep(i, n / 2) {
        if (s[i] == '1') {
            largest_tree = i;
        }
    }
    if (largest_tree == 0) {
        rep(i, n - 1) {
            cout << 1 << " " << i + 2 << endl;
        }
        return 0;
    }
    li head = 1;
    rep(i, largest_tree) {
        cout << head << " " << i + 2 << endl;
        cout << n - head + 1 << " " << n - i - 1 << endl;
        if (s[i] == '1') {
            head = i + 2;
        }
    }
    li ahead = n + 1 - head;
    cout << head << " " << ahead << endl;
    repp(i, largest_tree + 1, n - largest_tree - 1) {
        cout << head + 1 << " " << i + 1 << endl;
    }

    return 0;
}

