signed main(){
  string s;
  cin>>s;
  Int n=s.size();
  auto NO=[](){cout<<-1<<endl;exit(0);};
  if(s.back()=='1') NO();
  if(s.front()!='1') NO();

  s.insert(s.begin(),'0');
  for(Int i=1;i<n;i++)
    if(s[i]!=s[n-i]) NO();

  vector<vector<Int> > G(n);
  auto add_edge=
    [&](Int x,Int y){
      G[x].emplace_back(y);
      G[y].emplace_back(x);
    };
  Int idx=0;

  vector<Int> v(n+1,0);
  for(Int i=1;i<=n;i++) v[i]=v[i-1]+(s[i]=='1');
  if(v[n]==n-1){
    for(Int j=0;j+1<n;j++){
      add_edge(idx,idx+1);
      idx++;
    }
  }else{
    Int cur=0;
    for(Int i=n-1;i>=1;i--){
      if(s[i]=='1'){
	//cout<<i<<":"<<idx+1<<endl;
	add_edge(cur,idx+1);
	idx++;
	cur=idx;
	continue;
      }
      while(s[i]=='0') i--;
      while(n-(idx+1)>i) add_edge(cur,++idx);      
      i++;
    }
  }

  vector<Int> dp(n+1,0);
  function<Int(Int, Int)> dfs=
    [&](Int v,Int p){
      Int sub=1;
      for(Int u:G[v])
	if(u!=p) sub+=dfs(u,v); 
      if(~p) dp[sub]=dp[n-sub]=1;
      return sub;
    };
  dfs(0,-1);
  //for(Int i=1;i<=n;i++) cout<<dp[i]<<" "<<s[i]<<endl;
  for(Int i=1;i<=n;i++) assert(dp[i]==s[i]-'0');

  using P = pair<Int, Int>;
  vector<P> ans;
  for(Int v=0;v<n;v++)
    for(Int u:G[v]) if(u<v) ans.emplace_back(u,v);
  sort(ans.begin(),ans.end());
  for(auto p:ans) cout<<p.first+1<<" "<<p.second+1<<endl;
  return 0;
}

