#include <bits/stdc++.h>
using namespace std;
using ll = int64_t;
using P = pair<ll, ll>;
vector<P> ans;
string S;
bool solve(){
    vector<ll> v;
    if(S[0] == '0' || S[S.size() - 1] == '1') return 0;
    for(ll i = 1; i < S.size() / 2; i++){
        if(S[i] != S[S.size() - i - 2]) return 0;
        if(S[i] == '1' && S[i + 1] == '0') v.push_back(i);
    }
    if(S[S.size() / 2 - 1] == '1') v.push_back(S.size() / 2);
    ll child = 2;
    vector<ll> po;
    set<ll> se;
    for(ll i = 2; i <= S.size(); i++) se.insert(i);
    ll mini = -1;
    for(auto u : v){
        ll tmp;
        po.push_back(child);
        se.erase(child);
        if(mini == -1) mini = u;
        for(ll i = 0; i < mini; i++){
            ans.push_back(P(child, child + 1));
            se.erase(child);
            se.erase(child + 1);
            if(child + 1 > S.size()) return 0;
            child++;
            tmp = child;
        }
        for(ll i = mini; i < u; i++){
            ans.push_back(P(tmp, ++child));
            se.erase(child);
        }
        child++;
    }
    for(auto u : po) ans.push_back(P(1, u));
    for(auto u : se) ans.push_back(P(1, u));
    ll cnt = 0;
    for(auto u : ans) if(u.first == 1) cnt++;
    if(cnt <= 2) for(ll i = 0; i < S.size() - 2; i++) if(S[i] == '0') return 0;
    return 1;
}
int main(){
    cin >> S;
    if(solve()) for(P p : ans) cout << p.first << " " << p.second << endl;
    else cout << -1 << endl;
    return 0;
}

