void solve() {
    string S;
    cin >> S;
    int N = SIZE(S);

    if (S.front() == '0' || S.back() == '1') {
        cout << -1 << endl;
        return;
    }

    FOR(i, 0, N - 1) {
        if (S[i] != S[N - i - 2]) {
            cout << -1 << endl;
            return;
        }
    }

    V<P<int, int>> ans;
    ans.push_back(mp(1, 2));
    int par = 2;
    FOR(c, 3, N + 1) {
        ans.push_back(mp(par, c));
        if (S[c - 2] == '1') {
            par = c;
        }
    }

    for (auto p : ans) {
        cout << p.fst << " " << p.snd << endl;
    }
    return;
}


