const int N=1e5+5;

void no()
{
	cout<<"-1";
	exit(0);
}

int n;
string s;
vector<int> g[N];

void work()
{
	int prev=1;
	vector<int> pending;
	for(int i=2;i<=n;i++)
	{
		if(s[i]=='1')
		{
			if(i-prev==1)
			{
				g[i].push_back(prev);
				g[prev].push_back(i);
				prev=i;
			}
			else if((i-1)%prev==0)
			{	
				for(int j=1;j<=prev;j++)
				{
					for(int k=prev;j+k<i;k+=prev)
					{
						for(auto &it:g[j])
						{
							g[j+k].push_back(it+k);
						}
						if(j==prev)
							g[i].push_back(j+k), g[j+k].push_back(i);
					}
				}
				g[i].push_back(prev);
				g[prev].push_back(i);
				prev=i;
			}
			else
			{
				no();
			}
		}
	}
	for(int i=1;i<=n;i++)
	{
		for(auto &it:g[i])
		{
			if(it>i)
				cout<<i<<" "<<it<<endl;
		}
	}
}

