    if(S.back() == '1') return false;
    edges.resize(S.size());

    auto add_edge = [&](ll u, ll v) {
        if(u > v) swap(u, v);
        edges[u].push_back(v);
    };

    ll cur_root = 1;
    add_edge(0, 1);
    for(ll i = 1; i < S.size() - 1; i++) {
        if(S[i] == '1') {
            add_edge(cur_root, i + 1);
            cur_root = i + 1;
        } else {
            add_edge(cur_root, i + 1);
        }
    }
    return true;
}

