[[noreturn]] void impossible() {
    PRINTLN(-1);
    exit(0);
}

void solve() {
    auto S = '0' + RD<string>();
    i64 N = SIZE(S) - 1;
    DBG(S);
    DBG(N);

    if(S[1] != '1') impossible();
    if(S[N] != '0') impossible();
    REP(i, N/2+1) {
        if(S[i] != S[N-i]) impossible();
    }

    auto ans = vec_reserve<pair<i64,i64>>(N-1);
    {
        i64 k = 1;
        REP(i, N) {
            if(S[i] == '0') continue;
            i64 v = k-1;
            REP(_, i-k+1) {
                i64 to = k++;
                ans.emplace_back(v, to);
            }
        }
    }

    ASSERT(SIZE(ans) == N-1);

    for(const auto& e : ans) {
        i64 a,b; tie(a,b) = e;
        PRINTLN(a+1, b+1);  // 1-based
    }
}

