const int MAXN = 100000;

int n;
char s[MAXN + 2];

vector<pair<int, int>> ans;

bool solve() {
	if (s[n] == '1' || s[1] == '0' || s[n - 1] == '0') return false;
	vector<int> sz;
	for (int i = 2; i <= n - i; ++i) { if (s[i] != s[n - i]) return false; if (s[i] == '1') sz.PB(i); }
	sz.PB(n);

	ans.clear();
	int at = 0, prv = -1;
	REPSZ(i, sz) {
		int cnt = sz[i] - (i == 0 ? 0 : sz[i - 1]);
		vector<int> id(cnt); REP(j, cnt) id[j] = at++;
		if (prv != -1) ans.PB(MP(prv, id[0]));
		FORSZ(j, 1, id) ans.PB(MP(id[0], id[j]));
		prv = id[0];
	}
	return true;
}

void run() {
	s[0] = '0'; scanf("%s", s + 1); n = strlen(s + 1);
	if (!solve()) { printf("-1\n"); return; }
	REPSZ(i, ans) printf("%d %d\n", ans[i].first + 1, ans[i].second + 1);
}

int main() {
	run();
	return 0;
}

