            cnt.push_back(1);
            vector<P> ret;
            ret.push_back(P(1,2));
            int cnt2 = 2;
            int cnt3 = 3;
            for(int i = 0;i < cnt.size() - 1;i++) {
                int cnt4 = cnt.at(i) - cnt.at(i + 1);
                for(int j = 0;j < cnt4;j++) {
                    ret.push_back(P(cnt2,cnt3));
                    cnt3++;
                }
                cnt2 = cnt3 - 1;
            }
            for(int i = cnt.at(0) + 2;i <= N;i++) {
                ret.push_back(P(1,i));
            }
            for(int i = 0;i < ret.size();i++) {
                cout << ret.at(i).first << " " << ret.at(i).second << endl;
            }
        }
    }
}

