int n, m;
stack<int> ST;
bool vis[N];
int fa[N];
priority_queue<PA> q;
int main() {
    memset(vis, 0, sizeof vis);
    scanf("%s",s+1);
    n = strlen(s + 1);
    if (s[n] == '1' || s[1] == '0' || s[m = n - 1] == '0') {
