    if(ST.empty()) {
        ST.push(1);
    }
    while (!ST.empty()) {
        int a = ST.top();
        ST.pop();
        if (f) {
            vis[1] = vis[2] = 1;
            sons[1].l = 3;
            sons[1].r = 3 + a - 2;
            sons[2].l = 3 + a - 1;
            sons[2].r = n;
