            q.pop();
            cache.first -= a;
            q.push(cache);
            int son = sons[cache.second].l;
            fa[son] = cache.second;
            sons[cache.second].l += a;
            sons[son].l = son + 1;
            sons[son].r = son + a;
            q.push(make_pair(a - 1, son));
            vis[son] = 1;
        }
    }
