vector<vector<int>> construct(int n, string s) {
    vector<vector<int>> g(n);
    s.resize(n);
    vector<int> siz;
    for(int i = 1; i <= n; i++) {
        if(s[i - 1] == '1') {
            siz.push_back(i);
        }
    }
    reverse(all(siz));
    int k = siz.size();
    int sz = k;
    for(int i = 0; i < k; i++) {
        if(i) {
            g[i - 1].push_back(i);
        }
        int need = siz[i] - (i + 1 == k ? 0 : siz[i + 1]) - 1;
        for(int j = 0; j < need; j++) {
            g[i].push_back(sz++);
        }
    }
    return g;
}

