template <class T> using reversed_priority_queue = priority_queue<T, vector<T>, greater<T> >;
template <class T, class U> inline void chmax(T & a, U const & b) { a = max<T>(a, b); }
template <class T, class U> inline void chmin(T & a, U const & b) { a = min<T>(a, b); }
template <typename X, typename T> auto vectors(X x, T a) { return vector<T>(x, a); }
template <typename X, typename Y, typename Z, typename... Zs> auto vectors(X x, Y y, Z z, Zs... zs) { auto cont = vectors(y, z, zs...); return vector<decltype(cont)>(x, cont); }
template <typename T> ostream & operator << (ostream & out, vector<T> const & xs) { REP (i, int(xs.size()) - 1) out << xs[i] << ' '; if (not xs.empty()) out << xs.back(); return out; }

vector<pair<int, int> > solve(string const & s_) {
    const int n = s_.size();
    vector<bool> s(n + 1);
    REP (i, n) s[i + 1] = (s_[i] != '0');

    if (not s[1]) {
        return vector<pair<int, int> >();  // leaves are required
    }
    REP (i, n + 1) {
        if (s[i] != s[n - i]) {
            return vector<pair<int, int> >();  // invariant
        }
    }

    vector<pair<int, int> > edges;
    multimap<int, int> components;
    REP (i, n) {
        components.emplace(1, i);
    }
    REP (size, n / 2 + 1) if (s[size]) {
// dump(size);
        assert (components.begin()->first == 1);
        int acc = 1;
        int root = components.begin()->second;
        components.erase(components.begin());
// dump(root);
        vector<int> used;
        for (auto it = components.rbegin(); it != components.rend() and acc < size; ++ it) {
            if (acc + it->first <= size) {
                acc += it->first;
                used.push_back(it->first);
            }
        }
        for (int size_ : used) {
            auto it = components.find(size_);
            edges.emplace_back(root, it->second);
            components.erase(it);
        }
        assert (acc == size);
        components.emplace(size, root);
    }
    int root = components.rbegin()->second;
// dump(root);
    for (auto it = next(components.rbegin()); it != components.rend(); ++ it) {
// cerr << "edge " << root << " " << it->second << endl;
        edges.emplace_back(root, it->second);
    }
    return edges;
}

int main() {
    string s; cin >> s;
    auto edges = solve(s);
    if (edges.empty()) {
        cout << -1 << endl;
    } else {
        for (auto edge : edges) {
            int u, v; tie(u, v) = edge;
            cout << u + 1 << ' ' << v + 1 << endl;
        }
    }
    return 0;
}

