const int maxn = 123456;
char s[maxn];
int main(){
	scanf("%s", s + 1);
	int len = strlen(s + 1);
	if(s[len] == '1') cout << -1 << endl;
	else if(s[1] == '0' || s[len - 1] == '0') cout << -1 << endl;
//	else if(s[len / 2] == '0' || s[len - len/2] == '0') cout << -1 << endl;
	else {
		vector<pair<int,int> > eds;
		bool bad = false;
		int root = 1;
		int sz = 1;
		for(int i = 2; i <= len/2; i++){
			if(s[i] == '1' || s[len - i] == '1'){
				if(s[i] == '1' && s[len - i] == '1'){
					int add = i - sz;
					int newRoot = ++sz;
					eds.push_back({root, newRoot});
					add--;
					while(add--){
						int newSon = ++sz;
						eds.push_back({newRoot, newSon});
					}
					root = newRoot;		
				} else {
					bad = true;
				}
			}
		}
		if(bad) cout << -1 << endl;
		else {
			int newRoot = ++sz;;
			eds.push_back({root, newRoot});
			int add = len - sz;
			for(int i = 0; i < add; i++){
				int newSon = ++sz;
				eds.push_back({newRoot, newSon});
			}
			for(auto e : eds) cout << e.first << " " << e.second << endl;
		}
	}
	return 0;
}

