const int MAX = 2e5;
bool f[MAX + 1];

int it = 0;
vector<int> G[MAX];

void get(int size, int v) {
	assert(1 <= size);
	if (size == 1) return;
	--size;
	while (size >= 1) {
		int ns = -1;
		for (int i = size; i >= 1; i--) {
			if (f[i]) {
				ns = i;
				break;
			}
		}
		assert(ns != -1);
		if (ns >= 1) {
			int t = it++;
			G[v].push_back(t);
			G[t].push_back(v);
			get(ns, t);
		}
		size -= ns;
	}
}

