{
	string s;
	cin >> s;
	int n = s.size();
	if (s.front() != '1' || s.back() == '1') {
		cout << -1 << endl;
		return 0;
	}
	f[0] = true;
	for (int i = 1; i < n; i++) {
		if (s[i - 1] == '1') f[i] = true;
		if (s[i - 1] != s[n - i - 1]) {
			cout << -1 << endl;
			return 0;
		}
	}
	get(n, it++);
	assert(it == n);
	for (int i = 0; i < n; i++) {
		for (auto to : G[i]) if (to > i) {
			cout << i + 1 << ' ' << to + 1 << endl;
		}
	}
	return 0;
}

