  }
  for (int i = 1; i <= n / 2; ++i) {
    if (s[i] == '1' && s[n - i] == '0') {
      puts("-1");
      return 0;
    }
  }
  vector<pair<int, int>> ans;
  int ne = 2;
  for (int i = 2; i <= n / 2; ++i) {
    if (s[i] == '0') {
      continue;
    }
    int j = i;
    while (j + 1 <= n / 2 && s[j + 1] == '1') {
      ++j;
    }
    if (ne + j - 1 > n) {
      puts("-1");
      return 0;
    }
    ans.emplace_back(1, ne);
    ++ne;
    for (int k = 0; k < j - i; ++k) {
      ans.emplace_back(ne - 1, ne);
      ++ne;
    }
    int x = ne - 1;
    for (int k = 0; k < i - 1; ++k) {
      ans.emplace_back(x, ne);
      ++ne;
    }
    i = j;
  }
  while (ne <= n) {
    ans.emplace_back(1, ne);
    ++ne;
  }
  for (auto &e : ans) {
    printf("%d %d\n", e.first, e.second);
