  string s;
  cin >> s;
  int n = s.length();
  vector<pair<int, int>> grh;
  s = '$' + s;
  if (s[n] == '1') {
    cout << -1 << '\n';
    return 0;
  }
  int crr;
  stack<int> stk;
  for (int i = 1; i <= n / 2; i++) {
    if (s[i] != s[n - i]) {
      cout << -1 << '\n';
      return 0;
    }
    if (s[i] == '1') {
      crr = i;
      while (!stk.empty()) {
        int prv = stk.top();
        stk.pop();
        grh.push_back({prv, crr});
        grh.push_back({n + 1 - crr, n + 1 - prv});
      }
    }
    stk.push(i);
  }
  int lft = crr;
  int rgt = n + 1 - crr;
  if (lft + 1 == rgt) {
    grh.push_back({lft, rgt});
  } else if (lft + 1 < rgt) {
    int cen = lft + 1;
    grh.push_back({lft, cen});
    grh.push_back({cen, rgt});
    for (int i = cen + 1; i < rgt ; i++) {
      grh.push_back({cen, i});
    }
  }
  sort(grh.begin(), grh.end());
  for (auto e : grh) {
    cout << e.first << ' ' << e.second << '\n';
  }
  return 0;
}

