	ios::sync_with_stdio(false);

	string s;
	cin >> s;

	const int sz = (int)s.size();

	if (s.back() != '0' || s.front() != '1' || s[sz - 2] != '1') {
		cout << -1 << "\n";
		return 0;
	}

	for (int i = 0; i < sz / 2; i++) {
		if (s[i] != s[sz - i - 2]) {
			cout << -1 << "\n";
			return 0;
		}
	}

	auto star = [](int &now, const int size) {
		const int center = now++;
		for (int i = 1; i < size; i++, now++) {
			cout << center << " " << now << "\n";
		}
		return center;
	};

	int now = 1;
	int i = 1;
	for (; i < sz / 2; i++) {
		if (s[i] == '1') {
			DMP(i, now);
			const int st = star(now, i + 1);
			cout << st << " " << now << "\n";
			break;
		}
	}
	for (i++; i < sz / 2; i++) {
		if (s[i] == '1') {
			DMP(i, now);
			const int st = now++;
			for (int i = now; now <= i + 1; now++) {
				cout << st << " " << now << "\n";
			}
			cout << st << " " << now << "\n";
		}
	}
	star(now, sz - now + 1);

	return 0;
}

