using namespace std;

typedef pair<int, int> ii;

#define X first
#define Y second

string s;
int n;


vector <ii> ans;
void solve(){
    ans.push_back(ii(1, 2));
    int m = 2, head = 2;
    for(int i = 2; i <= (n + 1) / 2; i++){
        if (s[i] == '1'){
            ans.push_back(ii(head, m + 1));
            head = ++m;
            continue;
        }
        int need = 0;
        while (i + need <= (n + 1) / 2 && s[i + need] == '0') {
            need++;
        }
        if (i + need > (n + 1) / 2){
            for(int j = m + 1; j <= n; j++) 
                ans.push_back(ii(head , j));
            m = n;
            break;
        }
        for(int j = 1; j <= need; j++){
            ans.push_back(ii(head, m + j));
        }
        m += need;
        i += need - 1;
    }
    for(int j = m + 1; j <= n; j++)
        ans.push_back(ii(j, head));
    for(auto i: ans) cout << i.X << " " << i.Y << '\n';
}
int main(){
    cin >> s;
    n = s.length();
    s = '0' + s;
    for(int i = 0; i <= n; i++) if (s[i] != s[n - i]){
        cout << "-1" << endl;
        return 0;
    }
    if (s[1] == '0'){
        cout << "-1" << endl;
        return 0;
    }
    solve();
}

