void dfs(string s, int base){
  if (s == "11"){
    cout << base << " " << base + 1 << endl;
    cout << base + 1 << " " << base + 2 << endl;
    return;
  }
  if (s == "101"){
    cout << base << " " << base + 1 << endl;
    cout << base << " " << base + 2 << endl;
    cout << base << " " << base + 3 << endl;
    return;
  }
  if (s == "111"){
    cout << base << " " << base + 1 << endl;
    cout << base + 1 << " " << base + 2 << endl;
    cout << base + 2 << " " << base + 3 << endl;
    return;
  }



  ll n = s.size();
  if ((n + 1) % 2 == 0){
    if (s[n/2] == '1'){
      cout << base << " " << base + (n + 1)/2 << endl;
      dfs(s.substr(0, (n + 1)/2 - 1), base);
      dfs(s.substr(0, (n + 1)/2 - 1), base + (n + 1)/2);
    }
    else {
      cout << base << " " << base + n << endl;
      dfs(s.substr(0, n/2) + s.substr(n/2 + 1, n/2), base);
    }
  }
  else {
    ll mid = n/2 - 1;
    if (s[mid] == '1'){
      cout << base << " " << base + 1 << endl;
      cout << base << " " << base + 1 + n/2 << endl;
      dfs(s.substr(0, n/2 - 1), base + 1);
      dfs(s.substr(0, n/2 - 1), base + 1 + n/2);
    }
    else {
      cout << base << " " << base + n << endl;
      cout << base << " " << base + n - 1 << endl;
      dfs(s.substr(0, n/2 - 1) + s.substr(n/2 + 1, n/2 - 1), base);
    }
  }
}

