		vec[i].push_back(i + 1);
		vec[i + 1].push_back(i);
		cout << i << " " << i + 1 << endl;
	}
	int now = 0, node = sum + 1;
	REP(i, sum) {
		now++;
		if (now < memo[i - 1]) {
			for (int j = node + 1; j < node + memo[i - 1] - now; j++) {
				vec[i].push_back(j);
				vec[j].push_back(i);
				cout << i << " " << j << endl;
			}
			node += memo[i - 1] - now;
			now = memo[i - 1];
		}
	}
	for (int j = node + 1; j <= n; j++) {
		cout << sum + 1 << " " << j << endl;
	}
