	string s; cin >> s;
	int n = s.size();
	if(s[n - 1] != '0' || s[0] != '1') {
		cout << "-1\n";
		return 0;
	}
	for(int i = 0; i < n - 1; i++) {
		if(s[i] != s[n - 2 - i]) {
			cout << "-1\n";
			return 0;
		}
	}
	bool ok = 1;
	for(int i = 1; i < n - 2; i++) {
		if(s[i] != '0') {
			ok = 0;
		}
	}
	if(ok) {
		for(int i = 2; i <= n; i++) {
			cout << 1 << ' ' << i << '\n';
		}
		return 0;
	}
	auto gen = [&](int n, int base) {
		vector<pair<int, int> > edges;
		int now = 1 + base, tail = 1 + base;
		for(int i = 1; i < n; i++) {
			edges.emplace_back(tail, ++now);
			if(s[i] == '1' && i != n - 1) tail = now;
		}
		if(n >= 2 && s[n - 2] == '1') tail = now;
		return make_pair(edges, tail);
	};
	int szl, szr;
	if(n & 1) {
		szl = n / 2 + 1;
		szr = n - szl;
	} else {
		szl = n / 2 + (s[n/2-1]=='0');
		szr = n - szl;
	}
	auto xl = gen(szl, 0), xr = gen(szr, szl);
	auto ans = xl.fi;
	ans.insert(ans.end(), all(xr.fi));
	ans.emplace_back(xl.se, xr.se);
	sort(all(ans));
	for(auto &e : ans) {
		cout << e.fi << ' ' << e.se << '\n';
	}
	return 0;
}

