    else
      cout << -1 << endl;
    return 0;
  } else {
    set<ii> ans;

    auto add_edge = [&ans](int u, int v) {
      if(u > v) swap(u, v);
      ans.insert({u, v});
    };

    int ones = 0;
    for(char c : s) ones += c == '1';

    int mx = n;
    for(int i = 0; i < ones; i++) add_edge(i, i+1);

    int mn = 0;
    for(int i = 0; i < n/2; i++) {
      if(s[i] == '0') {
        add_edge(mn, --mx);
        if(i*2 != n)
          add_edge(ones - mn, --mx);
      } else {
        mn++;
      }
    }

    if((int)ans.size() != n-1) {
      cout << -1 << endl;
      return 0;
    }

    for(ii e : ans) cout << e.ff+1 << " " << e.ss+1 << "\n";
