  scanf("%s", s + 1);
  n = strlen(s + 1);
  for (int i = 1; i <= n; ++i) s[i] -= '0';
  if (s[n]) {
    puts("-1");
    return 0;
  }
  s[n] = 1;

  for (int i = 1; i < n; ++i) {
    if (s[i] != s[n - i]) {
      puts("-1");
      return 0;
    }
  }
  int cnt = 1;
  int root = 0;
  for (int i = 2; i <= n; ++i) {
    if (s[i]) {
      int new_root = cnt;
      ++cnt;
      edge.push_back({new_root, root});
      while (cnt < i) {
        edge.push_back({new_root, cnt});
        ++cnt;
      }
      root = new_root;
    }
  }

  for (int i = 0; i < n - 1; ++i) {
    printf("%d %d\n", edge[i].first + 1, edge[i].second + 1);
  }
}

