int solve(const string& S)
{
    int N = S.size() - 1;
    if (S[1] != '1' || S[N] != '0') return -1;
    char t = '1';
    int ans = 0;
    for (int i = 1; i + i <= N; i++) {
        if (S[i] != S[N-i]) return -1;
        if (t == S[i] && t == '1') ans = i;
        if (t != S[i] && t == '1') t = '0';
        if (t != S[i] && t == '0') return -1;
    }
    return ans;
}
