// x以上y以下のすべての自然数nに対してサイズnの連結成分が存在する
// 頂点の番号はzから開始
void add_edge(int x, int y, int z, vector<pair<int,int>> &v) {
    v.emplace_back(1,z);
    FOR(i,z,z+y-x) v.emplace_back(i,i+1);
    FOR(i,z+y-x+1,z+y) v.emplace_back(z+y-x,i);
}

