string s;
int n;
vector<Pii> edges;

void make_tree(){
    s[n-1] = '1';
    vector<int> one_indexes;
    for(int i=0;i<n;i++) if(s[i] == '1') one_indexes.push_back(i);
    for(int i=0;i<n-1;i++){
        // この内側ループを二分探索にする
        int j = *upper_bound(one_indexes.begin(), one_indexes.end(), i);
        if(i < j && j <= n) edges.emplace_back(i+1, j+1);
    }
}

int main(){
    std::ios::sync_with_stdio(0); cin.tie(0);
    cin >> s;
    n = s.length();

    bool flag = (s[0] == '1') && (s[n-1] == '0');
    for(int i=1;i<n/2&&flag;i++){
        if(s[i] != s[n-2-i]) flag = false;
    }
    bool all_zero = true;
    for(int i=1;i<n-1&&all_zero;i++){
        if(s[i] == '1') all_zero = false;
    }
    flag &= !all_zero;

    if(flag){
        make_tree();
        for(Pii e: edges) cout << e.first << " " << e.second << endl;
    }else{
        cout << -1 << endl;
    }
    return 0;
}

