void make_tree(int s, int next_s, int w){  //sは親の名前、wは全体のweight
    for(int i = w-1; i >= 1;){
        if(x[i] == 1){
            tree[s].push_back(next_s);
            make_tree(next_s, next_s+1, i);
            // cout << w << " " << i << endl;
            if(w-i > 1){
                int next_s2 = next_s + i;
                make_tree(s, next_s2, w-i);
            }
            break;
