  if(buf[n-1] != '0') return false;
  REP(i, n-1) {
    if(buf[i] != buf[n-2-i]) {
      return false;
    }
  }
  vector<pair<int,int>> es;
  es.push_back(make_pair(1, 2));
  int rest = n-2;
  int last = 2;
  for(int i = 1; rest > 0; ++i) {
    es.push_back(make_pair(last, i+2));
    if(buf[i] == '1') {
      last = i+2;
    }
    --rest;
  }
  REP(i, es.size()) {
    printf("%d %d\n", es[i].first, es[i].second);
  }
  return true;
}

int main(void) {
  scanf("%s", buf);
  n = strlen(buf);
  bool res = solve();
  if(!res) {
    puts("-1");
  }

  return 0;
}

