void go(int node , int lol){
	if(q.size()!=0){
		int num = q.top();
		ans.pb(mp(node , curr));
		lol -= num;
		q.pop();
		go(curr++ , num - 1);
	}
	for(int i = 0 ; i < lol ; i++){
		ans.pb(mp(node,curr++));
	}
}
