namespace adaptor = boost::adaptors;
using index_t = std::size_t;		

boost::optional<std::vector<std::set<index_t>>> run(std::string const& str)
{
	auto N = str.size();
	if (str.back() != '0' || str.front() != '1')
	{
		return boost::none;
	}
	std::vector<std::set<index_t>> ret(N);
	for (index_t i : boost::irange<index_t>(0, N - 1))
	{
		if (str[i] != str[N - 2 - i])
		{
			return boost::none;
		}
	}
	index_t last = 0;
	for (auto i : boost::irange<index_t>(1, N - 1))
	{
		if (str[i] == '1')
		{
			for (auto s : boost::irange(last, i))
			{
				ret[s].emplace(i);
			}
			last = i;
		}
	}
	ret[N - 2].emplace(N - 1);
	return ret;
}

void Main()
{
	std::string str;
	std::cin >> str;
	auto result = run(str);
	if (result)
	{
		for (auto i : boost::irange<index_t>(0, str.size()))
		{
			for (auto n : result->at(i))
			{
				std::cout << i + 1 << " " << n + 1 << std::endl;
			}
		}
	}
	else
	{
		std::cout << -1 << std::endl;
	}
}

