#define SZ(x) ((int)(x).size())

int const N = 1e5 + 5;

int a[N];
int n;

bool chk(std::string const& s) {
	for(int i = 0, j = SZ(s) - 2; i <= j; ++i, --j) {
		if(s[i] != s[j])
			return 0;
	}
	return 1;
}

int main() {
	std::string s;
	std::cin >> s;
	n = SZ(s);
	if(s[n - 1] == '1' || ::chk(s) == 0) {
		puts("-1");
		return 0;
	}

	auto it = s.end() - 1;

	static int fa[N];
	memset(fa, 0, sizeof(fa));
	for(int i = 1; i <= n; ++i) {
		it--;
		if(*it == '0') 
			continue;
		for(int j = i - 1; j >= 1; --j) {
			if(fa[j] != 0) 
				break;
			fa[j] = i;
		}
	}

	for(int i = n - 1; i >= 1; --i) {
		if(fa[i] != 0)
			break;
		fa[i] = n;
	}

	for(int i = 1; i < n; ++i) 
		std::cout << i << ' ' << fa[i] << '\n';

	return 0;
}

