ll m;
bool check(string s){
    int n=sz(s);
    int last=1;
    int p=0;
    bool ok=true;
    m=0;
    while(p<=(n-2)/2){
        if(last==1&&s[p]=='0')last=0;
        else if(last==0&&s[p]=='1'){
            ok=false;
            break;
        }
        if(s[p]!=s[n-p-2]){
            ok=false;
            break;
        }
        if(last==1)m++;
        p++;
    }
    if(m==0)return false;
    return ok;
}
int main(){
    string s;cin>>s;
    int n=sz(s);
    if(s[n-1]=='1'){
        cout<<-1<<endl;
        return 0;
    }
    if(!check(s)){
        cout<<-1<<endl;
        return 0;
    }
    vp ans;
    rrep(i,m){
        ans.pb({i,i+1});
    }
    for(int i=m+2;i<=n;i++)ans.pb({1,i});
    for(auto pp:ans)cout<<pp.fi<<" "<<pp.se<<endl;
    return 0;
}

