  int n;
  string s;
  vector<pair<int, int>> ans;
  Solver(string n) : n(n.size()), s(n){};

  void solve() {
    DBG(s)
    if (s.back() != '0' || s[0] == '0') {
      cout << -1 << endl;
      return;
    }
    DBG(s)
    s.pop_back();
    string r = s;
    reverse(r.begin(), r.end());
    DBG(s, r)
    if (r != s) {
      cout << -1 << endl;
      return;
    } else {
      int now = 2;
      int j = n / 2;
      for (; j >= 1; --j) {
        if (s[j - 1] == '1') break;
      }
      DBG(j)
      if (j == 1) {
        for (int i = 2; i <= n; ++i) {
          cout << "1 " << i << endl;
        }
        return;
      }
      addEdge(1, 2);
      for (int i = 2; i < j; ++i) {
        addEdge(now, i + 1);
        if (s[i - 1] == '1') {
          now = i + 1;
        }
      }
      DBG(now, ans)
      if (n == 2) {
      } else if (n % 2 == 0) {
        ans.emplace_back(now, n + 1 - now);
        for (int i = j + 1; i <= n + 1 - (j + 1); ++i) {
          ans.emplace_back(now, i);
        }
      } else {
        ans.emplace_back(now, j + 1);
        ans.emplace_back(n + 1 - now, j + 1);
        for (int i = j + 2; i <= n + 1 - (j + 1); ++i) {
          ans.emplace_back(j + 1, i);
        }
      }
    }
    for (int i = 0; i < ans.size(); ++i) {
      cout << ans[i].first << ' ' << ans[i].second << endl;
    }
  }
  void addEdge(int x, int y) {
    ans.emplace_back(x, y);
    ans.emplace_back(n + 1 - x, n + 1 - y);
  }
};

