using namespace std;

string s;

vector<pair<int,int>> subtree(int size) {
    int sz = -1;
    vector<pair<int,int>> ret;
    for(int i = size - 1;i > 0;i--) {
        if(s[i] == '1') {
            sz = i;
            break;
        }
    }
    if(sz == -1) {
        loop(i,1,size) {
            ret.push_back(make_pair(0,i));

        }
        return ret;
    }
    auto t1 = subtree(sz);
    auto t2 = subtree(size - sz);
    for(auto e:t1) {
        ret.push_back(e);
    }
    for(auto e:t2) {
        ret.push_back(make_pair(e.first + sz, e.second + sz));
    }
    ret.push_back(make_pair(0, sz));
    return ret;
}

int main(void) {
    cin >> s;
    if(s[0] == '0' || s[s.size()-1] == '1') {
        cout << -1 << endl;
        return 0;
    }
    for(int i = 0;i < s.size() - 1;i++) {
        if(s[i] != s[(s.size()-2)-i]) {
            cout << -1 << endl;
            return 0;
        }
    }
    auto res = subtree(s.size());
    for(auto e:res) {
        cout << e.first + 1 << " " << e.second + 1 << endl;
    }
}

