    }

    REP(i,N-1){
        int rem = N-2 - i;
        if(S[i] != S[rem]){
            cout << -1 << endl;
            return 0;
        }
    }

    queue<pair<int, int>> que;
    que.push(make_pair(N+1, 0));
    int point = N-1;
    int used = 0;
    while(!que.empty()){
        auto p = que.front();
        que.pop();
        int n = p.first-1;
        int v = p.second;
        //cout << "nv : " << n << " "  << v << endl;
        while(S[point] != '1')
            point--;

        bool update = false;
        for(int tmp = point; tmp >= 0; tmp--){
            int val = tmp+1;
            if(n - val < 0) continue;
            if(S[val-1] == '1'){
                E.emplace_back(v, ++used);
                if(val > 1)
                    que.push(make_pair(val, used));
                if(val != 1){
                    S[val-1] = '0';
                    if(N-1-(val-1) != 1)
                        S[N-1-(val-1)] = '0';
                }
                n -= val;
                tmp = n-1;
            }
        }

        REP(i,n){
            E.emplace_back(v, ++used);
        }
    }

    S[0] = '0';
    REP(i,N){
        if(S[i] == '1'){
            cout << -1 << endl;
            return 0;
        }
    }

    //cout << S << endl;

    auto p1 = E[0];
    auto p2 = E[1];
    E.erase(E.begin());
    E[0] = make_pair(p1.second, p2.second);
    for(auto&& edge : E){
        printf("%d %d\n", edge.first, edge.second);
    }

    return 0;
}

