bool ok;

void dfs(string s, vector<int> rt)
{
    int n = SZ(rt);
    for(int i = 0; i < n-1; i++){
        if(s[i] != s[n-2-i])ok = 0;
    }
    if(s[0] != '1' || s[n-1] != '0')ok = 0;
    bool link = 1;
    for(int i = 0; i < SZ(rt)-1; i++){
        if(s[i] != '1')link = 0;
    }
    if(SZ(rt) == 1 || !ok)return;
    else if(SZ(rt) == 2){
        ans.pb(mk(rt[0], rt[1]));
        return;
    }
    else if(link){
        for(int i = 1; i < SZ(rt); i++){
            ans.pb(mk(rt[i-1], rt[i]));
        }
    }
    else{
        bool flg = 1;
        for(int i = 1; i < SZ(rt)-2; i++){
            if(s[i] == '1'){
                int sz = i+1;
                string t;
                vector<int> nxt;
                for(int j = 0; j < SZ(rt); j += sz){
                    nxt.pb(rt[j]);
                    if(j+sz-1 < SZ(rt))t += s[j+sz-1];
                    for(int k = 1; k < sz && j+k < SZ(rt); k++){
                        ans.pb(mk(rt[j], rt[j+k]));
                    }
                }
                if(SZ(rt)%sz != 0)t += '0';
                dfs(t, nxt);
                flg = 0;
                break;
            }
        }
        if(flg){
            for(int i = 1; i < SZ(rt); i++){
                ans.pb(mk(rt[0], rt[i]));
            }
        }
    }
}

