int const MAX = 1e5 + 41;
char s[MAX];

int n;

void bad() {
	printf("-1\n");
	exit(0);
}

void solve() {
	if (s[1] == '0' || s[n] == '1' || s[n - 1] != '1') {
		bad();
	}
	fi(1, n - 1) {
		if (s[i] != s[n - i]) bad();
	}

	err("hello!|n");

	vpii edges;
	int root = 1;
	int x = 2;
	int p = 1;
	while (p < n) {
		if (s[p] == '1') {
			edges.pb(mp(root, x));
			root = x;
			x++;
			p++;
			continue;
		}
		int p1 = p + 1;
		while (p1 < n && s[p1] == '0') {
			p1++;
		}
		fi(1, p1 - p) {
			edges.pb(mp(root, x));
			x++;
		}
		edges.pb(mp(root, x));
		root = x;
		p = p1 + 1;
	}

	for (auto x : edges) {
		printf("%d %d\n", x.first, x.second);
	}
}

