VV<ll> edges;

bool solve() {
    string S;
    cin >> S;
    if(S[0] == '0') return false;
    if(S.back() == '1') return false;
    for(ll i = 2; i <= S.size() - 1; i++) {
        auto idx_i = i - 1;
        auto idx_j = (S.size() - i) - 1;
        if(S[idx_i] != S[idx_j]) return false;
    }
    edges.resize(S.size());

    auto add_edge = [&](ll u, ll v) {
        if(u > v) swap(u, v);
        edges[u].push_back(v);
    };

    ll cur_root = 1;
    add_edge(0, 1);
    for(ll i = 1; i < S.size() - 1; i++) {
        if(S[i] == '1') {
            add_edge(cur_root, i + 1);
            cur_root = i + 1;
        } else {
            add_edge(cur_root, i + 1);
        }
    }
    return true;
}

