#define Fr(i,n) for(int i=1;i<=(n);++i)
#define ifr(i,n) for(int i=(n)-1;i>=0;--i)
#define iFr(i,n) for(int i=(n);i>0;--i)

class ETree {
public:
    void solve(istream& in, ostream& out) {
        cin.tie(nullptr);
        ios::sync_with_stdio(false);
        int n;
        char C;
        string s;
        in>>s;
        n=s.length();
        s=' '+s;
        bool f=false;
        if(s[n]=='1'||s[1]=='0') f=true;
        Fr(i,n/2) if(s[i]!=s[n-i]) f=true;
        if(f){
            out<<-1<<endl;
            return;
        }

        int pa=1,nw=1;
        vector<int> m(n+1),c(n+1);
        Fr(i,n){
            m[i]=m[i-1];
            if(s[i-1]=='1') m[i]=i-1;
        }
        c[1]=n;
        vector<pair<int,int>> ans;
        Fr(i,n){
            if(c[i]==1) continue;
            c[++nw]=m[c[i]];ans.emplace_back(i,nw);
            c[i]-=m[c[i]];
            while(c[i]>1){
                c[++nw]=1;--c[i];
                ans.emplace_back(i,nw);
            }
        }
        for(auto p:ans) out<<p.first<<" "<<p.second<<endl;
    }
};

int main() {
    ETree solver;
    std::istream& in(std::cin);
    std::ostream& out(std::cout);
    solver.solve(in, out);
    return 0;
}

