        cout << "-1" << endl;
  		return (0);
	}

  	for (int i = 0; i < N / 2; i ++) {
    	if (str[i] != str[N - i - 2]) {
        	cout << "-1" << endl;
          	return (0);
        }
    }

  	int streak = -1;
  	for (int i = 0; i < (N + 1) / 2; i ++) {
    	if (streak != -1 && str[i] == '1') {
      		cout << "-1" << endl;
          	return (0);
        }

     	if (str[i] == '0' && streak == -1)
        	streak = i;
    }

  	if (streak == -1) {
		streak = (N + 1) / 2;
    }

	int tot = N - 1;
  	int cur = 2;
  	int prev = 1;
	while (tot > 0) {
    	prev = 1;

      	for (int i = 1; i <= streak; i ++) {
        	cout << prev << " " << cur << endl;
          	prev = cur;
          	cur ++;
          	tot --;

          	if (tot == 0)
            	break;
        }
    }
}

