const ll MOD = 1000000007;
const ll INF = 1000000000;
template <class T> T read(T &x) {
  char c;
  int flag = 1;
  while ((c = getchar()) < '0' || c > '9')
    if (c == '-')
      flag *= -1;
  x = c - '0';
  while ((c = getchar()) >= '0' && c <= '9')
    x = x * 10 + c - '0';
  x *= flag;
  return x;
}
string s;
int n;
int tot;
vector<pii> adj;
bool vis[100005];
void dfs(int x, int chosen, int dep){
  // cout << x << " " << chosen << " " << dep << endl;
  if(!vis[dep]) {
    cout << -1 << endl;
    exit(0);
  }
  // cout << x << " " << chosen << " " << tot<< endl;
  if(chosen == -1) return;
  int remain = chosen - 1;
  while(remain){
    int mx = -1;
    for(int i = remain; i >= 1 && mx == -1; --i)
      if(s[i] == '1') mx = i;
    ++tot;
    adj.pb(mp(x, tot));
    if(mx != -1) s[mx] = '0';
    else s[1] = '0';
    dfs(tot, mx, dep + 1);
    remain -= (mx == -1 ? 1 : mx);
  }
}
int main() {
  ios::sync_with_stdio(false);
  cin.tie(0);
  cin >> s;
  n = s.length();
  s = "#" + s;
  vis[0] = 1;
  if(s[n] == '1' || s[0] == '0') return cout<< -1 << endl, 0;
  for(int i = 1; i <= n; ++i)
    vis[i] = s[i] - '0';
  for(int i = n; i >= 1; --i){
    if(s[i] == '1'){
      s[i] = '0';
      dfs(++tot, i + 1, 0);
      break;
    }
  }
  for(auto i : adj)
    cout << i.fi << " " << i.se << endl;
}

