int main(){
  string s;
  cin >> s;
  int n = s.size();
  if(s.back() != '0' || s.front() != '1'){
    cout << "-1"<< endl;
    return 0;
  }
  s.pop_back();
  {
    string t =s ;
    reverse(all(t));
    if(s != t){
      cout << -1 << endl;
      return 0;
    }
  }

  int cnt = 3;
  vector<pair<int,int>> ans;
  vector<int> l,r;
  l.push_back(1);
  r.push_back(2);
  int lead = 0;
  for(int i = 2;i <= n - i;i++){
    if(s[i - 1] == '0'){
      lead++;
    }
    else{
      for(int j = 0;j < lead;j++){
        l.push_back(cnt++);
        r.push_back(cnt++);
      }
      int L = cnt++;
      int R = cnt++;
      for(int x : l){
        ans.push_back({x,L});
      }
      for(int x : r){
        ans.push_back({x,R});
      }
      l.clear();
      r.clear();
      l.push_back(L);
      r.push_back(R);
      lead = 0;
    }
  }
  if(cnt == n + 1){
    ans.push_back({l.front(),r.front()});
  }
  else{
    int CEN = cnt++;
    for(int x : l){
      ans.push_back({CEN,x});
    }
    for(int x : r){
      ans.push_back({CEN,x});
    }
    for(int i = cnt;i <= n;i++){
      ans.push_back({CEN,i});
    }
  }

  for(auto p : ans){
    cout << p.first << " " << p.second << endl;
  }
}

