using namespace std;
typedef pair<int, int> edge;
string s;
int cur = 0;
vector<edge> e;
void bad() {
	cout << "-1";
	exit(0);
}
signed main() {
	#ifdef BLU
	in("blu.inp");
	#endif
	ios_base::sync_with_stdio(false); cin.tie(0); cout.tie(0);
	cin >> s;
	int n = s.length();
	s = " " + s;
	if (s[1] == '0') bad();
	if (s[n] == '1') bad();
	/*
	Firstly, s[1] = 1 is obvious. s[n] = 0 is also obviouss
	Consider all subtrees of our tree. They must have a size v, such that all s[v] = '1'. Also, of all
	s[v] = '1' there must be at least a subtree of size v.
	This is easy to construct. Consider previously a subtree of size i - k was built and now we need
	a subtree of size i. Simply put the former as a subtree of the latter, then attach a bunch of leafs
	to the latter too.
	*/
	int lstsz = 1;
	cur = 1;
	fw (i, 2, n + 1) if (s[i] == '1') {
		//Last root was cur. For the k - 1 more nodes give them indices cur + 1, ..., cur + k - 1.
		//The new root is cur + k
		int k = i - lstsz;
		e.pb({cur + k, cur});
		fw (j, cur + 1, cur + k) e.pb({cur + k, j});
		cur = cur + k;
