bool chk(std::string const& s) {
	for(int i = 0, j = SZ(s) - 2; i <= j; ++i, --j) {
		if(s[i] != s[j])
			return 0;
	}
	return 1;
}

int main() {
	std::string s;
	std::cin >> s;
	n = SZ(s);
	if(s[n - 1] == '1' || ::chk(s) == 0) {
		puts("-1");
