bool solve(vi& a) {
  int n = a.size()-1;
    if (a[n] == 1) return false;
    if (a[1] == 0) return false;
    rep1(i, n - 1) if (a[i] != a[n - i]) return false;

    vector<ii> conn;

    int h = n / 2;
    int pre = 1, last_good = 1;
    for (int i=2; i<=h; ++i) {
#ifdef DEBUG
        fprintf(stderr, "a[%d] = %d\n", i, a[i]);
#endif
        conn.pb(ii(pre, i));
        if (last_good >= 0) {
          pre = last_good + 1;
          last_good = -1;
        }
        if (a[i]) {
          last_good = i;
        }
    }
    if (a[h]) {
        conn.pb(ii(h, h+1));
        pre = h+1;
        for (int i=h+2; i<=n; ++i) {
            conn.pb(ii(pre, i));
        }
    } else {
        pre = h;
      for (int i = h + 1; i <= n; ++i) {
        conn.pb(ii(pre, i));
      }
    }

    for (ii p: conn) {
        printf("%d %d\n", p.first, p.second);
    }
    return true;
}

