vii edges;

void addEdge(int u, int v) {
	edges.push_back({ u, v });
}

void solve() {
	string s;
	cin >> s;
	int n = sz(s);
	if (s[n - 1] == '1' || s[0] == '0') {
		cout << -1;
		return;
	}
	for (int i = 0; i <= n - 2; ++i) {
		if (s[i] != s[n - 2 - i]) {
			cout << -1;
			return;
		}
	}

	int k = (n - 1) / 2;
	int last = 0;
	rep(i, 0, k) {
		addEdge(last, i + 1);
		if (s[i] == '1')
			last = i + 1;
	}

	if (n & 1) {
		for (int i = 0, _m = sz(edges); i < _m; ++i) {
			int u = edges[i].first, v = edges[i].second;
			if (v == last) swap(u, v);
			if (u == last) {
				addEdge(u, n - 1 - v);
			} else {
				addEdge(n - 1 - u, n - 1 - v);
			}
		}
	} else {
		if (s[n / 2 - 1] == '1') {
			for (int i = 0, _m = sz(edges); i < _m; ++i) {
				addEdge(n - 1 - edges[i].first, n - 1 - edges[i].second);
			}
			addEdge(last, n - 1 - last);
		} else {
			for (int i = 0, _m = sz(edges); i < _m; ++i) {
				int u = edges[i].first, v = edges[i].second;
				if (v == last) swap(u, v);
				if (u == last) {
					addEdge(u, n - 2 - v);
				} else {
					addEdge(n - 2 - u, n - 2 - v);
				}
			}
			addEdge(last, n - 1);
		}
	}

	for (auto& p : edges) {
		cout << p.first + 1 << ' ' << p.second + 1 << '\n';
	}
}

