    if(S[N-1] == '1' || S[0] == '0'){
        cout << -1 << endl;
        return 0;
    }

    REP(i,N-1){
        int rem = N-2 - i;
        if(S[i] != S[rem]){
            cout << -1 << endl;
            return 0;
        }
    }

    queue<pair<int, int>> que;
    que.push(make_pair(N+1, 0));
    int point = N;
    int used = 0;
    while(!que.empty()){
        auto p = que.front();
        que.pop();
        int n = p.first-1;
        int v = p.second;
        //cout << "nv : " << n << " "  << v << endl;
        while(S[point] != '1')
            point--;

        bool update = false;
        for(int tmp = point; tmp >= 0; tmp--){
            int val = tmp+1;
            if(n - val < 0) continue;
            if(S[val-1] == '1'){
                E.emplace_back(v, ++used);
                que.push(make_pair(val, used));
                if(val != 1){
                    S[val-1] = '0';
                    S[N-1-(val-1)] = '0';
                }
                n -= val;
            }
        }

        REP(i,n){
            E.emplace_back(v, ++used);
        }
    }

    S[0] = '0';
    REP(i,N/2){
        if(S[i] == '1'){
            cout << -1 << endl;
