int main() {
	cin.tie(0);
	ios::sync_with_stdio(false);
	string s;
	cin >> s;
	int n = s.size();
	vi v(n + 1);
	v[0] = 1;
	REP(i, n)v[i + 1] = s[i] - '0';
	bool ok = true;
	if (v[n] == 1 || v[1] == 0)ok = false;
	REP(i, (n - 1) / 2) {
		if (v[i + 1] != v[n - 1 - i])ok = false;
	}
	ll cnt = 0;
	for (int i = 2; i < n / 2; ++i) {
		if (v[i] == 1 && v[i + 1] == 0) {
			cnt += i;
		}
	}
	if (cnt > n || !ok) {
		cout << -1 << endl;
		return 0;
	}
	vector<pii> ans;
	int num = 2;
	vector<pii> t;
	int prev = 0;
	for (int i = 2; i < n / 2; ++i) {
		if (v[i] == 0 && v[i + 1] == 1) {
			prev = i;
		}
		else if (v[i] == 1 && v[i + 1] == 0) {
			t.push_back({ prev,i });
		}
	}

	REP(i, t.size()) {

		int k = num + t[i].first;

		REP(j, t[i].first) {
			ans.push_back({ k,num });
			num++;
		}

		REP(j, t[i].second - t[i].first - 1) {
			ans.push_back({ num,num++ });
		}
		ans.push_back({ num++,1 });

	}
	bool f = true;
	for (int i = 2; i <= n / 2; ++i) {
		if (v[i] == 0)f = false;
	}
	if (f) {
		REP(i, n - 1)ans.push_back({ i + 1,i + 2 });
	}
	while (num <= n) {
		ans.push_back({ num++,1 });
	}
	REP(i, n - 1)cout << ans[i].first << " " << ans[i].second << endl;
}

