int build_tree(int v, int k)
{
    if (k == 1)
        return v;
    v--;
    int i = 2;
    int pr = 1;
    while (i <= k)
    {
        int e = i;
        while (e <= k && !a[e])
            e++;
        int u = build_tree(v + i, min(e - i + 1, k - i + 1));
        cout << pr + v << " " << u << "\n";
        pr = u - v;
        i = e + 1;
    }
    return pr + v;
}

