		return cout << -1 << endl, 0;
	}

	for (int i = 1; i <= n - 1; ++i) {
		if (s[i] != s[n - i]) {
			return cout << -1 << endl, 0;
		}
	}

	vector <int> pos;
	for (int i = 1; i <= n / 2; ++i) if (s[i] == '1') {
		pos.push_back(i);
	}

	int cur = 1;
	for (int i = 1; i < pos.size(); ++i) {
		add(cur, cur + 1);
		++cur;
		for (int j = 1; j <= pos[i] - pos[i - 1] - 1; ++j) {
			add(cur, cur + j);
		}
		cur += pos[i] - pos[i - 1] - 1;
	}

	for (int i = cur + 1; i <= n; ++i) {
		add(i, cur);
	}

	//~ dfs(1);
	//~ for (int i = 1; i <= n; ++i) {
		//~ if (s[sz[i]] != '1' || s[n - sz[i]] != '1') {
			//~ return cout << -1 << endl, 0;
		//~ }
	//~ }

	for (auto e : ed) {
