const int N = 1e5 + 3;
int n;
char s[N];
bool valid() {
	for (int i = 0; i <= n / 2; ++i)
		if (s[i] != s[n - i])
			return false;
	return s[1] == '1';
}
int main() {
//	freopen("input.in", "r", stdin);
	scanf("%s", s + 1);
	s[0] = '0';
	n = strlen(s + 1);
	if (!valid()) {
		puts("-1");
		return 0;
	}
	int lenPref = 0;
	while (s[lenPref + 1] == '1')
		++lenPref;
	vector<pair<int, int>> edges;
	int j = 1;
	bool pref = false;
	for (int i = lenPref + 1; i <= n / 2; ++i) {
		if (s[i] == '1') {
			edges.emplace_back(1, ++j);
			int tmp = j;
			if (!pref) {
				for (int k = 1; k <= lenPref; ++k) {
					edges.emplace_back(j, j + 1);
					++j;
				}
				pref = true;
				for (int k = lenPref + 1; k < i; ++k)
					edges.emplace_back(tmp, ++j);
			} else {
				for (int k = 1; k < i; ++k)
					edges.emplace_back(tmp, ++j);
			}
			if (j > n) {
				puts("-1");
				return 0;
			}
		}
	}
	if (!pref) {
		for (int k = 1; k <= lenPref; ++k) {
			edges.emplace_back(j, j + 1);
			++j;
		}
	}

	while (j < n)
		edges.emplace_back(1, ++j);
	for (auto p: edges) {
		printf("%d %d\n", p.first, p.second);
	}
	return 0;
}

