      for(int i=0;i<sz-lastSz-1;++i) {
        edge.push_back(make_pair(curRoot,nodePos++));
      }
      lastSz = sz;
      lastRoot = curRoot;
    }
  }
  assert(edge.size()==n-1);
  for(int i=0;i<edge.size();++i) {
    printf("%d %d\n", edge[i].first,edge[i].second);
  }
}

