char s[N+1];

int cnt = 2,sz[N],freq[N],n;
vector<int> g[N];
vector< pii > E;

void addEdge(int u , int v){
	E.pb(mp(u,v));
	g[u].pb(v);
	g[v].pb(u);
}
void dfs(int u , int p){
	sz[u] = 1;
	for(auto v : g[u]){
		if(v==p)continue;
		dfs(v,u);
		sz[u] += sz[v];
	}
	if(p != -1){
		freq[sz[u]] = 1;
		freq[n-sz[u]] = 1;
	}
}

int main(){
	scanf("%s",s);
	n = strlen(s);
	for(int i = n ;i >= 1 ; --i)
		s[i] = s[i-1];
	if(s[n]=='1' || s[1]=='0'){
		puts("-1");
		return 0;
	}
	for(int i = 1; i <= n/2 ; ++i){
		int cm = n-i;
		if(s[i] != s[cm]){
			puts("-1");
			return 0;
		}
	}
	int last = 1,lsSize = 1;
	for(int i = 2 ; i <= n/2 ; ++i){
		if(s[i]=='1'){
			int rem = i-lsSize-1;
			int me = cnt++;
			while(rem--){
				addEdge(cnt++,me);
			}
			addEdge(me,last);
			last = me;
			lsSize = i;
		}
	}
	if(cnt <= n){
		int here = cnt++;
		addEdge(last,here);
		while(cnt <= n){
			addEdge(here,cnt++);
		}
	}
	dfs(1,-1);
	for(int i = 1;  i <= n ; ++i){
		if(freq[i] != s[i]-'0'){
			puts("-1");
