int main() {
    string s; cin >> s;
    const int n = s.size();
    bool ng = s[0] == '0' || s.back() == '1';
    for(int i = 0; i < (n - 1) / 2; ++i) {
        ng |= s[i] != s[n - 2 - i];
    }
    if(ng) {
        assert(false);
        cout << -1 << endl;
        return 0;
    }
    if(count(begin(s), end(s), '1') <= 2) {
        for(int i = 2; i <= n; ++i) {
            cout << 1 << ' ' << i << endl;
        }
        return 0;
    }
    vector<pii> ans;
    int now_a = 1, iter = 2, prev_a = -1;
    for(int i = 1; i < n / 2; ++i) {
        if(s[i] == '1') {
            if(prev_a != -1) {
                ans.emplace_back(prev_a, now_a);
            }
            for(int j = now_a + 1; j <= iter; ++j) {
                ans.emplace_back(now_a, j);
            }
            prev_a = now_a;
            now_a = iter + 1;
        }
        iter++;
    }
    {
        const int m = ans.size() + 1;
        const int k = n / m;
        const int num = k * m;
        vector<pii> ans2;
        for(int i = 0; i < k; ++i) {
            for(auto& p : ans) {
                ans2.emplace_back(p.first + i * m, p.second + i * m);
            }
        }
        ans = move(ans2);
        if(n % num > 1) {
            cout << -1 << endl;
            return 0;
        } else if(n % num == 0 && k > 2) {
            cout << -1 << endl;
            return 0;
        } else {
            if(n % num == 0) {
                ans.emplace_back(prev_a, prev_a + m);
            } else {
                for(int i = 0; i < k; ++i) {
                    ans.emplace_back(prev_a + i * m, n);
                }
            }
        }
    }
    sort(begin(ans), end(ans));
    assert((int)ans.size() == n - 1);
    for(auto& p : ans) {
        cout << p.first << " " << p.second << endl;
    }
}

