int main() {
    string s; cin >> s;
    const int n = s.size();
    bool ng = s[0] == '0' || s.back() == '1';
    if(n & 1) {
        ng |= s[n / 2 - 1] != '1' || s[n / 2] != '1';
    } else {
        ng |= s[n / 2 - 1] != '1';
    }
    for(int i = 0; i < (n - 1) / 2; ++i) {
        ng |= s[i] != s[n - 2 - i];
    }
    if(ng) {
        cout << -1 << endl;
        return 0;
    }
    if(count(begin(s), end(s), '1') == 2) {
        for(int i = 2; i <= n; ++i) {
            cout << 1 << ' ' << i << endl;
        }
        return 0;
    }
    vector<pii> ans;
    int now_a = 1, iter = 2;
    for(int i = 1; i < n / 2; ++i) {
        ans.emplace_back(now_a, iter);
        ans.emplace_back(now_a + (n + 1) / 2, iter + (n + 1) / 2);
        if(s[i] == '1') {
            now_a = iter;
        }
        iter++;
    }
    if(n & 1) {
        ans.emplace_back(now_a, now_a + 1);
        ans.emplace_back(now_a + 1, now_a + 2);
    } else {
        ans.emplace_back(now_a, now_a + 1);
    }
    sort(begin(ans), end(ans));
    assert((int)ans.size() == n - 1);
    for(auto& p : ans) {
        cout << p.first << " " << p.second << endl;
    }
}

