  int lft = crr;
  int rgt = n + 1 - crr;
  if (lft + 1 == rgt) {
    grh.push_back({lft, rgt});
  } else if (lft + 1 < rgt) {
    int cen = lft + 1;
    grh.push_back({lft, cen});
    grh.push_back({cen, rgt});
    for (int i = cen + 1; i < rgt ; i++) {
      grh.push_back({cen, i});
    }
  }
  sort(grh.begin(), grh.end());
