{
	if (!v[1]) return false;
	rep(i, N+1) {
		if (v[i] != v[N-i]) return false;
	}
	rep(i, N+1) {
		if (v[i] && i != N - i) {
			v[N-i] = false;
		}
	}
	return true;
}

void solve()
{
	if (!check()) {
		cout << -1 << endl;
		return;
	}
	int root = N-1;
	cout << N << " " << N - 1 << endl;
	int tyo = N - 2;
	reps(i, 2, N) {
		cout << root << " " << tyo << endl;
		if (v[i]) {
			root = tyo;
		}
		tyo--;
	}
}

