const int MAXN = 1e5+5;

int n, p[MAXN];
int a[MAXN];
char s[MAXN];

int main(){
	scan(s);
	n = strlen(s);
	FOR(i,0,n) a[i+1] = s[i]-'0';
	if(a[1]!=1 || a[n]==1){
		printf("-1\n");
		return 0;
	}
	FOR(i,1,n){
		if(a[i] != a[n-i]){
			printf("-1\n");
			return 0;
		}
	}
	stack<int> stk;
	stk.push(n);
	int v = -1;
	FOR(i,2,n){
		if(a[i] == 0){
			stk.push(n-i+1);
		}else{
			v = n-i+1;
			while(!stk.empty()){
				int u = stk.top(); stk.pop();
				p[u] = v;
			}
			stk.push(v);
		}
	}
	v = 1;
	while(!stk.empty()){
		int u = stk.top(); stk.pop();
		p[u] = v;
	}
	FOR(i,2,n+1) printf("%d %d\n",p[i],i);

}

