void get(int size, int v) {
	assert(1 <= size);
	--size;
	while (size >= 1) {
		int ns = *prev(st.upper_bound(size));
		if (ns >= 1) {
			int t = it++;
			G[v].push_back(t);
			G[t].push_back(v);
			get(ns, t);
		}
		size -= ns;
	}
