bool pre_judge(string& s, int n) {
    if (s[n - 1] == '1') return false;
    if (s[0] == '0') return false;
    if (s[n - 2] == '0') return false;
    for (int i = 1; i < n / 2; i++) {
        if (s[i] != s[n - 2 - i]) return false;
    }
    return true;
}

int main() {
    cin.tie(0);
    ios::sync_with_stdio(false);
    string s;
    cin >> s;
    int n = s.size();
    if (!pre_judge(s, n)) {
        cout << -1 << endl;
        return 0;
    }

    vector< vector<int> > g(n);
    g[0].push_back(1);
    int cur = n - 1;
    for (int i = 1; i < n - 1; ) {
        cur--;
        for (int j = cur; j > 0; j--) {
            if (s[j - 1] == '0') continue;
            int idx = i + 1;
            while (cur > j) {
                g[i].push_back(idx);
                idx++;
                cur--;
            }
            g[i].push_back(idx);
            i = idx;
            break;
        }
        if (cur == 0) break;
    }

    for (int i = 0; i < n; i++) {
        for (int j : g[i]) {
            cout << i + 1 << " " << j + 1 << endl;
        }
    }
    return 0;
}

