  bool ok = true;

  if (S[1] == '0' || S[N - 1] == '0' || S[N] == '1')
    ok = false;

  vector<bool> flag((N / 2) + 1, false);
  bool all = true;
  FOR(i, 1, (N / 2) + 1) {
    if (S[i] != S[N - i])
      ok = false;
    flag[i] = (S[i] == '1');
    all &= flag[i];
  }
  // 無理
  if (!ok) {
    cout << -1 << endl;
    return 0;
  }
  // 全部直列
  if (all) {
    FOR(i, 1, N) { cout << i << " " << (i + 1) << endl; }
    return 0;
  }
  ll min = 0;
  FOR(i, 1, (N / 2) + 1) {
    if (flag[i])
      min = i;
    else
      break;
  }

  ll sum = 1;     // root
  bool v = false; // trueならまとめられる
  ll count = 0;
  FOR(i, min + 1, (N / 2) + 1) {
    if (flag[i]) {
      sum += i;
      count++;
      if (i >= min + 2)
        v = true;
    }
  }
  if (v == false)
    sum += min;

  if ((!v && count < 2) || (v && count < 3))
    sum += 1;

  // 個数が足りないので無理
  if (sum > N) {
    cout << -1 << endl;
    return 0;
  }

  if (!v)
    FOR(i, 1, min + 1) { cout << i << " " << (i + 1) << endl; }
  ll now = min + 1;

  FOR(i, min + 1, (N / 2) + 1) {
    if (flag[i]) {
      now++;
      ll base = now;
      cout << 1 << " " << base << endl;
      if (v && i >= min + 2) {
        REP(j, min) {
          now++;
          cout << now - 1 << " " << now << endl;
        }
        REP(j, i - min) {
          now++;
          cout << base << " " << now << endl;
        }
        v = false;
      } else {
        REP(j, i) {
          now++;
          cout << base << " " << now << endl;
        }
      }
    }
  }
  FOR(i, now + 1, N + 1) cout << 1 << " " << i << endl;

  return 0;
}

