        return 0;
    }
    else if (n == 2){
        std::cout << 1 << ' ' << 2 << std::endl;
        return 0;
    }
    for(int i = 1; i < n-1; i++){
        if(G[i] != G[n-i-2]){
            //std::cout << "hello" << std::endl;
            std::cout << -1 << std::endl;
            return 0;
        }
    }
    std::vector<body> bodies;
    int body_length = 0;
    for(int i = 0; i < n-1; i++){
        if(G[i] == '1'){
            body tmp;
            tmp.idx = i+2;
            body_length++;
            bodies.push_back(tmp);
            if (i == 0){
                bodies[0].legs.push_back(1);
            }
        }
        else {
            if(i != n-1) bodies[body_length-1].legs.push_back(i+2);
        }
    }
    for(int i = 0; i < body_length; i++){
        int body_idx = bodies[i].idx;
        if(i != 0){
            std::cout << body_idx << " " << bodies[i-1].idx << std::endl;
        }
        for(auto const& cidx: bodies[i].legs){
            std::cout << cidx << " " << body_idx << std::endl;
        }
    }

    return 0;

}

