		szr = n - szl;
	}
	auto xl = gen(szl, 0), xr = gen(szr, szl);
	auto ans = xl.fi;
	ans.insert(ans.end(), all(xr.fi));
	ans.emplace_back(xl.se, xr.se);
	sort(all(ans));
	for(auto &e : ans) {
		cout << e.fi << ' ' << e.se << '\n';
	}
