const int maxn = 100005;

char S[maxn], RS[maxn];
using pii = std::pair<int, int>;
std::vector<pii> E;
int main() {
  scanf("%s", S + 1);
#ifdef LOCAL
  puts(S + 1);
#endif
  int n = strlen(S + 1);
  if(S[1] == '0' || S[n] == '1') {
    puts("-1"); return 0;
  }
  std::copy(S + 1, S + n, RS + 1);
  std::reverse(RS + 1, RS + n);
  for(int i = 1; i < n; i ++) {
    if(RS[i] != S[i]) {
      puts("-1"); return 0;
    }
  }
  int las = 1, lv = 1, cnt = 1;
  for(int i = 2; i <= (n / 2); i ++) {
    if(S[i] == '1') {
      int np = ++ cnt;
      E.push_back({np, las});
      int c = i - lv - 1;
      while(c --) E.push_back({np, ++ cnt});
      lv = i; las = np;
    }
  }
  int rt = ++ cnt;
  E.push_back({las, rt});
  int c = n - lv - 1;
  while(c --) E.push_back({rt, ++ cnt});
  for(const pii &e : E) {
    printf("%d %d\n", e.first, e.second);
  }
  return 0;
}

