void solve() {
	string temp; cin >> temp;
	vector<int> S(temp.size());
	FOR(i, 0, S.size()) {
		S[i] = temp[i] - '0';
	}
	if (S[0] == 0) {
		cout << -1 << endl;
		return;
	}
	if (S.back() == 1) {
		cout << -1 << endl;
		return;
	}
	FOR(i, 1, S.size() - 1) {
		int cur = i + 1;
		int tar = temp.size() - cur;
		if (S[cur - 1] != S[tar - 1]) {
			cout << -1 << endl;
			return;
		}
	}

	vector<pii> edges;
	int cnt = 0;
	FOR(i, 1, S.size()) {
		bool f = (S[i] == 1);
		if ((i != S.size() - 1) and (not f)) ++cnt;
		else {
			FOR(j, i - cnt, i) {
				edges.emplace_back(i, j);
			}
			edges.emplace_back(i, i - cnt - 1);
			cnt = 0;
		}
	}

	for (auto &a : edges) {
		cout << a.first + 1 << " " << a.second + 1 << endl;
	}
}

