int WriteStar(int nodes)
{
    static auto next_node = 1;

    auto centre = next_node;
    next_node += 1;

    for (int i = 2; i <= nodes; i += 1) {
        cout << centre << " " << next_node << "\n";
        next_node += 1;
    }
    return centre;
}

int main()
{
    string str;
    getline(cin, str);

    auto good = (str[0] == '1' && str.back() == '0');
    for (size_t i = 0; i < str.size() / 2 && good; i += 1) {
        good = (str[i] == str[str.size() - i - 2]);
    }

    if (!good) {
        cout << "-1\n";
        return 0;
    }

    int nodes_left = str.size();
    auto last_centre = -1;

    for (size_t i = 1; i < str.size() / 2; i += 1) {
        if (str[i] == '1') {
            auto nodes_needed = i + 1 - (str.size() - nodes_left);
            auto new_centre = WriteStar(nodes_needed);

            if (last_centre != -1) {
                cout << last_centre << " " << new_centre << "\n";
            }
            last_centre = new_centre;
            nodes_left -= nodes_needed;
        }
    }

    auto new_centre = WriteStar(nodes_left);
    if (last_centre != -1) {
        cout << last_centre << " " << new_centre << "\n";
    }

    return 0;
}

