#include <bits/stdc++.h>
#define REP(i, n) for (int i = 0; (i) < (int)(n); ++ (i))
#define REP3(i, m, n) for (int i = (m); (i) < (int)(n); ++ (i))
using namespace std;

vector<pair<int, int> > solve(string const & s_) {
    const int n = s_.size();
    vector<bool> s(n + 1);
    REP (i, n) s[i + 1] = (s_[i] != '0');

    if (not s[1]) {
        return vector<pair<int, int> >();  // leaves are required
    }
    REP (i, n + 1) {
        if (s[i] != s[n - i]) {
            return vector<pair<int, int> >();  // invariant
        }
    }

    vector<pair<int, int> > edges;
    int root = 0;
    int root_size = 1;
    int next = 1;
    REP3 (size, 2, n + 1) if (s[size] or size == n) {
        edges.emplace_back(root, next);
        root = next;
        ++ root_size;
        ++ next;
        while (root_size < size) {
            edges.emplace_back(root, next);
            ++ root_size;
            ++ next;
        }
    }
    return edges;
}

int main() {
    string s; cin >> s;
    auto edges = solve(s);
    if (edges.empty()) {
        cout << -1 << endl;
    } else {
        for (auto edge : edges) {
            int u, v; tie(u, v) = edge;
            cout << u + 1 << ' ' << v + 1 << endl;
        }
    }
    return 0;
}

