int psz = 0;
int new_node() { return ++psz; }

vector<pair<int, int> > ed;

void add_edge(int u, int v) { ed.push_back({u, v}); }

void solve()
{
	if(s[0] == '0' || s[n - 1] == '1')
	{
		cout << -1 << endl;
		return;
	}

	s.pop_back();

	string rev = s;
	reverse(rev.begin(), rev.end());

	if(rev != s)
	{
		cout << -1 << endl;
		return;
	}

	s = " " + s;

	int last = -1;
	while(psz < n)
	{
		while(s[psz] == '0')
		{
			int x = new_node();
			add_edge(x, last);
		}

		int prv = last;
		last = new_node();
		if(prv != -1)
			add_edge(last, prv);
	}

	for(auto it: ed)
		cout << it.first << " " << it.second << endl;
}

