      vis[now] = 1;
      cnt++;
      if(par[le+cnt] == -1) par[le+cnt] = id1;
      if(par[ri+cnt] ==-1) par[ri+cnt] = id2;
      dfs(now,le+cnt,ri+cnt);
   }
   return;
}

