#define REP(i, n) for(int i = 0; i < (int)(n); ++i)
#define FOR(i, m, n) for(int i = (int)(m); i < (int)(n); ++i)


int main()
{
    string s;
    cin >> s;

    int n = s.size();

    // 木が構築できるかどうか
    bool can_build = true;
    if(s[0] == '0' or s[n-1] == '1') can_build = false;
    REP(i, n-1){
        if(s[i] != s[n-i-2]) can_build = false;
    }

    // 具体的な木の構築
    vector<int> G(n-1);  // G[i]: i の親
    int root = 1, child = 0;
    while(root < n){
        while(root < n-1 and s[root] == '0') ++root;
        FOR(i, child, root) G[i] = root;
        child = root;
        ++root;
    }

    // output the answer
    if(can_build) REP(i, n-1) cout << i+1 << " " << G[i]+1 << endl;
    else cout << -1 << endl;

    return 0;
}

