using namespace std;

#define NMAX 100002

char c[NMAX];
vector <int> v[NMAX];

bool possible(const int n) {
    if (c[1] == '0')
        return false;
    if (c[n] == '1')
        return false;
    for (int i = 1; i < n; i++) {
        if (c[i] != c[n - i])
            return false;
    }
    return true;
}

int main()
{
    ios::sync_with_stdio(false);

    // ifstream cin("code.in");
    cin >> (c + 1);
    const int n = strlen(c + 1);

    if (!possible(n)) {
        cout << "-1\n";
        return 0;
    }

    v[1].push_back(2);
    int current = 2;

    for (int i = 2; i <= (n >> 1); i++) {
        if (c[i] == '0')
            continue;
        int prev = current;
        while (current != i) {
            v[prev].push_back(++current);
        }
        v[prev].push_back(++current);
    }

    for (int i = current + 1; i <= n; i++) {
        v[current].push_back(i);
    }

    int cnt = 0;
    for (int i = 1; i <= n; i++) {
        for (const int x : v[i]) {
            if (i < x) {
                cout << i << " " << x << '\n';
                cnt++;
            }
        }
    }
    assert(cnt == n - 1);
    return 0;
}

