void dfs(int rem, int from = 1) {
    if (rem == 0) return;
    int me = -1;

    if (str[rem - 1] != str[N - rem - 1]) bye("-1");
    // これから作る辺を切るとremとN-remに分割
    if (str[rem - 1] == '1') {
        edges.emplace_back(from, curr);
        me = curr;
        if (++curr > N) answer();
        dfs(rem - 1, me);
    }
    else {
        // remに分割されるのを回避したい
        while (true) {
            dfs(rem - 1, from);
            // edges.emplace_back(from, curr);
            // int it = curr;
            // if (++curr > N) answer();
            // dfs(rem - 2, it);
        }
    }
}

