    if (s.back() != '0') {
        cout << -1 << endl;
        return;
    }
    if (s.front() != '1') {
        cout << -1 << endl;
        return;
    }

    deque<int> a;
    for (int i = 0; i < (s.size() + 1) / 2; i++) {
        if (s[i] == '1') {
            if (s[s.size() - i - 2] == '0') {
                cout << -1 << endl;
                return;
            }
            a.push_back(i + 1);
        }
    }

    output(0, newV());
    int cnt = 2;
    int now = 1;
    a.pop_front();
    while (a.size()) {
        while (cnt < a.front()) {
            output(now, newV());
            cnt++;
        }
        int x = newV();
        output(now, x);
        cnt++;
        now = x;
        a.pop_front();
    }
    while (cnt < n) {
        output(now, newV());
        cnt++;
    }


}


