	vector<int> vs;
	for (int i = 1; i <= n / 2; i++)
	{
		if (s[i-1] != s[n-i-1])
		{
			fail();
		}
		if (s[i-1] == '1')
		{
			sum += 1L * i;
			vs.push_back(i);
		}
	}
	if (sum + 1 > n)
	{
		fail();
	}
	vector<int> g[n];
	int now = 1;
	for (int v : vs)
	{
		int r = now++;
		g[0].push_back(r);
		for (int i = 0; i < v - 1; i++)
		{
			g[r].push_back(now++);
		}
	}
	for (int i = now; i < n; i++)
	{
		g[0].push_back(now++);
	}
	for (int i = 0; i < n; i++)
	{
		for (int v : g[i])
		{
			cout << i + 1 << ' ' << v + 1 << '\n';
		}
	}
