#define int long long

string S;

vector<int> tree;
vector<int> revTree;

signed main() 
{
    cin >> S;

    if(S[S.length()-1] != '0' || S[0] != '1') {
        cout << -1 << endl;
        return 0;
    }

    S = "x" + S;

    for(int i = 2; i < S.length()-1; i++) {
        if(S[i] != S[S.length()-1-i]) {
            cout << -1 << endl;
            return 0;
        }
    }

    int N = S.length()-1;
    int nextIndex = 1;
    int nowIndex = 0;
    tree.resize(N, -1);

    for(int i = 1; i <= (N+1)/2; i++) {
        cerr << "i: " << i << endl;
        if(S[i] == '1') {
            cerr << "1 " << nowIndex << " " << nextIndex << endl;
            tree[nowIndex] = nextIndex;
            nextIndex++;
            nowIndex++;
        } else {
            cerr << "0 " << nowIndex << " " << nextIndex << endl;
            tree[nextIndex] = nowIndex;
            nextIndex++;
        }
    }

    int oldNextIndex = nextIndex;
    int oldNowIndex = nowIndex;

    revTree.resize(N, -1);
    nextIndex = N-2;
    nowIndex = N-1;
    for(int i = N-1; (N+1)/2+1 < i; i--) {
        if(S[i] == '1') {
            revTree[nowIndex] = nextIndex;
            nextIndex--;
            nowIndex--;
        } else {
            revTree[nextIndex] = nowIndex;
            nextIndex--;
        }
    }

    revTree[nowIndex] = oldNowIndex;

    cerr << "tree" << endl;
    for(int i : tree) {
        cerr << i << endl;
    }
    cerr << "revtree" << endl;
    for(int i : revTree) {
        cerr << i << endl;
    }

    for(int i = 0; i < N; i++) {
        if(tree[i] != -1) {
            cout << i+1 << " " << tree[i]+1 << endl;
        } else if(revTree[i] != -1) {
            cout << i+1 << " " << revTree[i]+1 << endl;
        }
    }

    return 0;
}

