const int MAXN = 1e5 + 10;

int n;
bool can[MAXN];

bool read() {
    string ss;
    if (!(cin >> ss)) {
        return 0;
    }
    n = sz(ss);
    memset (can, 0, sizeof can);
    forn(i, n) {
        can[i + 1] = ss[i] - '0';
    }
    return 1;
}

int ptr;
int getv() {
    return ptr++;
}

vii ans;
void addE(int v, int u) {
    ans.pb(mp(v, u));
}

void go(int p, vi& ss, int pos) {
    int v = getv();
    assert(v < n);
    addE(p, v);
    const int s = ss[pos];
    if (s == 1) {
        return;
    }
    assert(pos > 0);
    const int nxt = ss[pos - 1];
    assert(nxt < s);
    forn(it, s - nxt - 1) {
        int u = getv();
        addE(v, u);
    }
    go(v, ss, pos - 1);
}

bool solve() {
    ptr = 0;
    ans.clear();

    if (!can[1]) {
        return 0;
    }
    forn(s, n + 1) {
        if (can[s] != can[n - s]) {
            return 0;
        }
    }

    vi ss;
    forn(s, n / 2 + 1) {
        if (can[s]) {
            ss.pb(s);
        }
    }

    int root = getv();
    go(root, ss, sz(ss) - 1);
    while (1) {
        int v = getv();
        if (v >= n) {
            break;
        }
        addE(root, v);
    }

    for (const auto& e : ans) {
        cout << e.fst + 1 << " " << e.snd + 1 << endl;
    }
    return 1;
}

