	list<int> zeros;
	REP(i, nodes)if (s[i] == '0')zeros.push_back(i + 1);

	// add more node
	while (!zeros.empty()) {
		if (zeros.size() == 1) {
			int now = zeros.front(); zeros.pop_front();
			if (now == nodes + 1 - now) {
				edges.push_back({ now,edges.size() + 2 });
			}
			else {
				cout << -1 << endl;
				return;
			}
		}
		else {
			int nowl = zeros.front(); zeros.pop_front();
			int nowr = zeros.back(); zeros.pop_back();
			if (nodes + 1 - nowl == nowr) {
				edges.push_back({ nowl,edges.size() + 2 });
			}
			else {
				cout << -1 << endl;
				return;
			}
		}
	}

	//exception
	if (edges.size() > s.size() - 1) {
		cout << -1 << endl;
		return;
	}

	//rest
	while (edges.size() < s.size() - 1)edges.push_back({ edges.size() + 2,2 });

	//output
	for (auto p : edges)cout << p.first << " " << p.second << endl;
}


