        while (node <= n) {
          connect(rightNode, node);
          node++;
        }
        break;
      } else {
        for (int i = 0; i < prev - r; i++) {
          connect(rightNode, node);
          node++;
        }
        rightNode = node - 1;
      }
    }
  }

  for (auto p : ans) {
    printf("%d %d\n", p.first, p.second);
  }

  return 0;
}

