    bool ng = s[0] == '0' || s.back() == '1';
    for(int i = 0; i < (n - 1) / 2; ++i) {
        ng |= s[i] != s[n - 2 - i];
    }
    if(ng) {
        cout << -1 << endl;
        return 0;
    }
    vector<pii> ans;
    int now_a = 1, iter = 2, prev_a = -1;
    for(int i = 1; i < n; ++i) {
        if(s[i] == '1') {
            if(prev_a != -1) {
                ans.emplace_back(prev_a, now_a);
            }
            for(int j = now_a + 1; j <= iter; ++j) {
                ans.emplace_back(now_a, j);
            }
            prev_a = now_a;
            now_a = iter + 1;
        }
        iter++;
    }
    ans.emplace_back(prev_a, n);
    sort(begin(ans), end(ans));
    for(auto& p : ans) {
        cout << p.first << " " << p.second << endl;
    }
