std::vector<PAIR> res;
bool calc(std::string s) {
	int n = s.size();
	if (s.front() == '0') return false;
	if (s.back() == '1') return false;
	REP(i, n - 1) {
		if (s[i] != s[n - i - 2]) return false;
	}
	int pre = 0;
	REP(i, n - 1) {
		res.emplace_back(PAIR(pre, i + 1));
		if (s[i] == '1') {
			pre = i + 1;
		}
	}
}

signed main() {
	INIT;

	VAR(std::string, s);
	int n = s.size();
	if (!calc(s)) {
		OUT(-1)BR;
	}
	else {
		REP(i, n - 1) {
			OUT(res[i].first + 1) SP OUT(res[i].second + 1)BR;
		}
	}

	return 0;
}

