int a[N];
vector<int> adj[N];
int sub[N];
bool vis[N],mark[N];
int dfs(int node) {
	vis[node] = true;
	sub[node] = 1;
	for(int it : adj[node]) {
		if(!vis[it]) {
			sub[node] += dfs(it);
		}
	}
	return sub[node];
}
