		return 0;
	}
	int currRoot = 2;
	adj[2].push_back(1);
	adj[1].push_back(2);
	vector<pair<int,int>> ed;
	ed.push_back({2,1});
	for(i = 1;i < n-1;i++) {
		int id = i+2;
		if(str[i] == '1') {
			adj[id].push_back(currRoot);
			adj[currRoot].push_back(id);
			ed.push_back({currRoot,id});
			currRoot = id;
		}
		else {
			adj[currRoot].push_back(id);
			adj[id].push_back(currRoot);
			ed.push_back({currRoot,id});
		}
	}
	dfs(currRoot);
	for(i = 1;i <= n;i++) {
