using namespace std;

const int N = 100005;

char s[N];
int n;
int lef[N];
int p[N];

void solve(){

    lef[1] = n-1;
    priority_queue<pair<int, int>> q;
    q.emplace(n-1, 1);

    int ne = 2;
    int sz, u;
    for(int i = n / 2; i >= 1; i--) if(s[i] == '1'){
        tie(sz, u) = q.top();
        q.pop();
        if(sz < i){
            printf("-1\n");
            exit(0);
        }
        lef[u] -= i;
        lef[ne] = i-1;
        if(lef[u]) q.emplace(lef[u], u);
        if(lef[ne]) q.emplace(lef[ne], ne);
        p[ne] = u;
        ne++;
    }

    u = 1;
    for(; ne <= n; ne++){
        while(!lef[u]) u++;
        p[ne] = u;
        lef[u]--;
    }
}

