fun solve(): List<Pair<Int, Int>>? {
    val input = readLine()!!
    val n = input.length
    val bits = ("0" + input).map { it == '1' }.toBooleanArray()
    if (bits[n]) return null
    for (i in 1..(n - 1)) {
        if (bits[i] && !bits[n - i]) return null
    }

    val edges = mutableListOf<Pair<Int, Int>>()
    var prev = 0
    for (i in 2..(n - 1)) {
        if (bits[i]) {
            if (prev == 0) {
                for (j in 1..(i - 1)) {
                    edges.add(Pair(j, i))
                }
            } else {
                edges.add(Pair(prev, i))
                for (j in (prev + 1)..(i - 1)) {
                    edges.add(Pair(j, i))
                }
            }
            prev = i
        }
    }
    edges.add(Pair(n - 1, n))

    return edges
}

