    static class TaskE {
        public void solve(int testNumber, InputReader in, OutputWriter out) {
            String s = in.next();

            int n = s.length();

            s = " " + s;

            if (s.charAt(n) == '1') {
                out.println(-1);
                return;
            }

            for (int i = 1; i < n; i++) {
                if (s.charAt(i) != s.charAt(n - i)) {
                    out.println(-1);
                    return;
                }
            }

            int cv = 2;

            int[] p = new int[n + 1];

            Arrays.fill(p, -1);

            p[1] = 2;

            int cs = 2;

            for (int i = 3; i <= n; i++) {
                if (s.charAt(cs) == '1') {
                    p[cv] = i;
                    cv = i;
                } else {
//                p[cv] = i;
//                cv = i;
//                i++;
//                while (s.charAt(i) == '0')
//                {
//
//                }

                    p[i] = cv;
                }
                cs++;
            }

            for (int i = 1; i <= n; i++) {
                if (p[i] != -1) {
                    out.println(i + " " + p[i]);
                }
            }
        }

    }

    static class InputReader {
        private InputStream stream;
        private byte[] buf = new byte[1024];
        private int curChar;
        private int numChars;
        private InputReader.SpaceCharFilter filter;

        public InputReader(InputStream stream) {
            this.stream = stream;
        }

        public static boolean isWhitespace(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }

        public int read() {
            if (numChars == -1) {
                throw new InputMismatchException();
            }
            if (curChar >= numChars) {
                curChar = 0;
                try {
                    numChars = stream.read(buf);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (numChars <= 0) {
                    return -1;
                }
            }
            return buf[curChar++];
