            char[] s = in.next().toCharArray();
            int n = s.length;
            boolean[] comp = new boolean[n];
            for (int i = 0; i < n; i++) {
                comp[i] = (s[i] == '1');
            }
            if (comp[n - 1]) {
                out.println(-1);
                return;
            }
            if (n == 2) {
