					node.add(new Node(1, i + 2));
					break;
				} else {
					node.add(new Node(1, i + 1));
				}
			}
			for(int i = from - 1; i < s.length() - 1; i++) {
				node.add(new Node(from, i + 2));
				if(s.charAt(i) != '0') {
					from = i + 2;
				}
			}
			for(Node e : node) {
				System.out.println(e.getFrom() + " " + e.getTo());
			}
		} else {
			System.out.println(-1);
		}

	}
}

