        for (int i = 1; i < input.length(); ++i) {
            if (input.charAt(i - 1) == '1') {
                pw.println(currentEnd + " " + (i + 1));
                currentEnd = (i + 1);
            } else {
                pw.println(currentEnd + " " + (i + 1));
            }
        }
    }
}

