        boolean can = s.charAt(n) == '0' && s.charAt(0) == '1';
        for (int i = 0; i < n; i++) {
            can &= s.charAt(i) == s.charAt(n - 1 - i);
            a[i] = s.charAt(i) == '1';
        }
        if (can) {
            int last = n;
            for (int i = n - 1; i >= 0; i--) {
                out.println(last + 1, i + 1);
