    static class TaskE {
        public void solve(int testNumber, InputReader in, OutputWriter out) {
            String s = in.readString();
            int n = s.length();

            if (s.charAt(n - 1) == '1' || s.charAt(0) == '0') {
                out.printLine(-1);
                return;
            }

            for (int i = 1; i < n / 2; i++) {
                if (s.charAt(i) != s.charAt(n - 2 - i)) {
                    out.printLine(-1);
                    return;
                }
            }

            int parent = n;
            for (int i = n - 2; i >= 0; i--) {
                out.printLine((i + 1) + " " + parent);
                if (s.charAt(i) == '1') parent = i + 1;
            }
        }

    }

