      int ptr = 0;
      int[][] edge = new int[n][2];
      int now = 0;
      int v = 1;
      for (int i = 0; i <= n / 2; i ++) {
        if (a[i] == 1) {
          edge[ptr ++] = new int[] {now, v};
          now = v;
          v ++;
        } else {
          edge[ptr ++] = new int[] {now, v ++};
