import java.io.ByteArrayInputStream;
import java.io.IOException;
import java.io.InputStream;
import java.io.PrintWriter;
import java.util.Arrays;
import java.util.InputMismatchException;

public class Main {
	static InputStream is;
	static PrintWriter out;
	static String INPUT = "";

	static void solve()
	{
		char[] s = ns().toCharArray();
		int n = s.length;
		if(s[n-1] == '1'){
			out.println(-1);
			return;
		}
		if(s[0] == '0'){
			out.println(-1);
			return;
		}
		for(int i = 0, j = n-2;i < j;i++,j--){
			if(s[i] != s[j]){
				out.println(-1);
				return;
			}
		}

		int root = 1;
		int gen = 2;
		int[][] es = new int[n-1][];
		int p = 0;
		for(int i = 1;i < n;i++){
			if(s[i] == '1'){
				int pre = gen;
				int nroot = gen++;
				es[p++] = new int[]{root, nroot};
				for(int j = i+1 - pre;j > 0;j--){
					es[p++] = new int[]{nroot, gen++};
				}
				root = nroot;
			}
		}
		es[p++] = new int[]{root, n};
		assert p == n-1;

		for(int i = 0;i < n-1;i++){
			out.println(es[i][0] + " " + es[i][1]);
		}
	}

