    static boolean inValid(char[] a){
        int n = a.length-1;
        if(a[1]=='0'||a[n]=='1') return true;
        for(int i=1;i<=n/2;i++){
            if(a[i]!=a[n-i]) return true;
        }
        return false;
    }
