		if (s[0] != '1' || s[^1] != '0' || Enumerable.Range(0, n / 2).Any(i => s[i] != s[^(i + 2)])) { Console.WriteLine(-1); return; }

		var dp = new int[n];
		for (int t = n, i = 1; i < n; dp[i] = t, t = s[i - 1] == '1' ? i : t, i++) ;
		Console.WriteLine(string.Join("\n", dp.Select((x, i) => $"{x} {i}").Skip(1)));
	}
}

