    /// <summary>
    /// https://atcoder.jp/contests/arc103/tasks/arc103_c
    /// </summary>
    public class QuestionF : AtCoderQuestionBase
    {
        public override IEnumerable<object> Solve(TextReader inputStream)
        {
            var canMake = inputStream.ReadLine().Select(c => c == '1').ToArray();
            var n = canMake.Length;

            if (canMake[^1])
            {
                yield return -1;
                yield break;
            }

            var end = false;
            var max = 0;
            for (int i = 0; i < n / 2; i++)
            {
                if ((canMake[i] ^ canMake[^(i + 2)]) || (end && canMake[i]))
                {
                    yield return -1;
                    yield break;
                }
                else if (canMake[i])
                {
                    max = i + 1;
                }
                else
                {
                    end = true;
                }
            }

            if (max == 0)
            {
                yield return -1;
                yield break;
            }

            var from = 1;
            var to = 2;
            var uni = n - max - 1;
            for (int i = 0; i < uni; i++)
            {
                yield return $"{from} {to++}";
            }

            while (to <= n)
            {
                yield return $"{from} {to}";
                from = to++;
            }
        }
    }
}

