internal partial class Solver {
    public void Run() {
        var s = ns();
        var ans = Solve(s);
        cout.WriteLine(string.Join("\n", ans));
    }

    private IEnumerable<string> Solve(string s) {
        var ng = new[] { "-1" };
        var n = s.Length;
        if (s[0] == '0') return ng;
        if (s[n - 1] == '1') return ng;
        for (int i = 0, j = n - 2; i < j; i++, j--) {
            if (s[i] != s[j]) return ng;
        }
        var ans = new List<string>();

        int current = 1, index = 1;
        int size = 1;

        for (int _ = 0; _ < n - 1; _++) {
            if (s[size - 1] == '0') {
                ans.Add(string.Format("{0} {1}", current, ++index));
                size++;
            } else {
                var parent = ++index;
                ans.Add(string.Format("{0} {1}", current, parent));
                current = parent;
                size++;
            }
        }

        return ans;
    }
}

