using System;
using System.Linq;

class E
{
	static void Main()
	{
		var s = Console.ReadLine();
		var n = s.Length;

		if (s[0] != '1' || s[^1] != '0' || Enumerable.Range(0, n / 2).Any(i => s[i] != s[n - 2 - i])) { Console.WriteLine(-1); return; }

		var dp = new int[n];
		var t = n;
		for (int i = 1; i < n; i++)
		{
			dp[i] = t;
			if (s[i - 1] == '1') t = i;
		}
		Console.WriteLine(string.Join("\n", Enumerable.Range(1, n - 1).Select(i => $"{dp[i]} {i}")));
	}
}

using System;
