namespace Competitive
{
    internal class Solution
    {
        public int N;
        public long MOD = 1000000007;
        public string S;

        public void Run()
        {
            S = Console.ReadLine();
            N = S.Length;

            if (S[0] == '0' || S[S.Length - 1] == '1')
            {
                Console.WriteLine(-1);
                return;
            }

            for (int i = 0; i < N - 1; i++)
            {
                if (S[i] != S[N - 2 - i])
                {
                    Console.WriteLine(-1);
                    return;
                }
            }

            int x = 1;
            for (int i = 0; i < N - 1; i++)
            {
                if (S[i] == '1')
                {
                    Console.WriteLine("{0} {1}", x, i + 2);
                    x++;
                }
                else
                {
                    Console.WriteLine("{0} {1}", x, i + 2);
                }
            }
        }
    }

