using System;
using System.Collections.Generic;
using System.Linq;
using System.Numerics;
using System.Text;

class Solution
{
    static void Main(string[] args)
    {
        int[] s = Array.ConvertAll(Console.ReadLine().ToCharArray(), c => c - '0');

        bool ok = s[0] == 1 && s[s.Length - 1] == 0;
        for (int i = 0; i < s.Length - 1; i++)
        {
            if (s[i] != s[s.Length - 2 - i]) ok = false;
        }
        if (!ok)
        {
            Console.WriteLine(-1);
        }
        else
        {
            List<Edge> edges = new List<Edge>();
            Stack<int> children = new Stack<int>();
            for (int v = 1; v <= s.Length; v++)
            {
                if (s[v - 1] == 1 || v == s.Length)
                {
                    while (children.Count > 0)
                    {
                        edges.Add(new Edge(v, children.Pop()));
                    }
                }
                children.Push(v);
            }

            foreach (var e in edges)
            {
                Console.WriteLine($"{e.u} {e.v}");
            }
        }
    }
}

struct Edge
{
    public int u, v;
    public Edge(int u, int v)
    {
        this.u = u;
        this.v = v;
    }
}

