namespace AtCoder
{
    class Program
    {
        private static string Read() { return Console.ReadLine(); }
        private static int ReadInt() { return int.Parse(Read()); }
        private static long ReadLong() { return long.Parse(Read()); }
        private static double ReadDouble() { return double.Parse(Read()); }
        private static int[] ReadInts() { return Array.ConvertAll(Read().Split(), int.Parse); }
        private static long[] ReadLongs() { return Array.ConvertAll(Read().Split(), long.Parse); }
        private static double[] ReadDoubles() { return Array.ConvertAll(Read().Split(), double.Parse); }

        static IEnumerable<int[]> Solve(string S)
        {
            int N = S.Length;
            if (S.Last() != '0') { return null; }
            if (S.First() != '1') { return null; }
            for (int i = 0; i < N - 2 - i; ++i)
            {
                if (S[i] != S[N - 2 - i]) { return null; }
            }
            var set = new List<int> { 0 };
            for (int i = 1; i < N; ++i) { if (S[i] == '1') { set.Add(i + 1); } }
            set.Add(N);
            var edges = new List<int[]>();
            for (int i = 1; i < set.Count; ++i)
            {
                for (int j = set[i - 1] + 1; j < set[i]; ++j)
                {
                    edges.Add(new int[] { j, set[i] });
                }
                if (i + 1 < set.Count)
                {
                    edges.Add(new int[] { set[i], set[i + 1] });
                }
            }
            return edges;
        }
        static void Main(string[] args)
        {
            var edges = Solve(Read());
            if (edges == null)
            {
                Console.WriteLine(-1);
            }
            else
            {
                foreach (var edge in edges) { Console.WriteLine(string.Join(" ", edge)); }
            }
        }
    }
}

