using System;
using System.Collections.Generic;
using System.Linq;

class E
{
	static void Main()
	{
		var s = Console.ReadLine();
		var n = s.Length;

		if (s[^1] != '0' || Enumerable.Range(0, n / 2).Any(i => s[i] != s[n - 2 - i]) || s[0] != '1') { Console.WriteLine(-1); return; }

		var sub = s[..(n / 2)];
		var c1 = sub.TakeWhile(c => c == '1').Count();
		if (sub.Skip(c1).All(c => c == '0'))
		{
			var r = Enumerable.Range(1, c1).Select(i => $"{i} {i + 1}")
				.Concat(Enumerable.Range(c1 + 2, n - c1 - 1).Select(i => $"1 {i}"));
			Console.WriteLine(string.Join("\n", r));
		}
		else
		{
			var gs = Enumerable.Range(1, n / 2).Skip(c1).Where(i => s[i - 1] == '1').ToArray();
			var g0 = n - gs.Sum();
			if (gs.Length <= 2 ? g0 < 0 : g0 <= 0) { Console.WriteLine(-1); return; }

			var r = new List<string>();
			var id = g0 == 0 ? 0 : 1;

			if (g0 == 0)
				r.Add($"1 {gs[0] + 1}");
			for (int i = 2; i <= g0; i++)
				r.Add($"1 {++id}");

			foreach (var g in gs)
			{
				var root = ++id;
				if (g0 > 0)
					r.Add($"1 {root}");
				for (int i = 0; i < c1; i++)
				{
					var nid = ++id;
					r.Add($"{nid - 1} {nid}");
				}
				for (int i = c1 + 1; i < g; i++)
					r.Add($"{root} {++id}");
			}

			Console.WriteLine(string.Join("\n", r));
		}
	}
}

