class Solve{
    public Solve(){}
    StringBuilder sb;
    ReadData re;
    public static int Main(){
        new Solve().Run();
        return 0;
    }
    void Run(){
        sb = new StringBuilder();
        re = new ReadData();
        Calc();
        Console.Write(sb.ToString());
    }
    void Calc(){
        string S = re.s();
        int N = S.Length;
        if(S[N-1] == '1'){
            sb.Append("-1\n");
            return;
        }
        if(S[0] == '0'){
            sb.Append("-1\n");
            return;
        }
        for(int i=1;i<N-1;i++){
            if(S[i-1] != S[N-i-1]){
                sb.Append("-1\n");
                return;
            }
        }
        int p = 2;
        int last = 1;
        for(int i=2;i<=N/2;i++){
            if(S[i-1] == '1'){
                for(int j=last;j<p;j++){
                    sb.Append(j + " " + p + "\n");
                }
                last = p;
                p++;
            }
            else{
                p++;
            }
        }
        for(int j=last;j<=N;j++){
            if(j != p){
                sb.Append(j + " " + p + "\n");
            }
        }
    }
}
