    E[] t;
    auto n = s.length.to!int;
    int e = 1, last;
    void add_node(int i) {
        t ~= E(1, ++e);
        auto o = e;
        foreach (_; 0..i-last-1) {
            t ~= E(e, ++e);
        }
        auto ee = e;
        foreach (_; 0..last) {
            t ~= E(ee, ++e);
        }
    }
    foreach (int i; 0..n/2) {
        if (s[i] == '0' && s[i-1] == '1') {
            add_node(i);
        } else {
            if (i == 0 || s[i-1] == '0') last = i;
        }
    }
    if (s[n/2-1] == '1') add_node(n/2);
    while (e < n) {
        t ~= E(1, ++e);
    }

    foreach (x; t) {
        writefln("%d %d", x[0], x[1]);
    }
}

