void main()
{
    auto s = readln.chomp;
    if (s[0] == '0' || s[$-2] == '0' || s[$-1] == '1') {
        writeln(-1);
        return;
    }
    auto n = s.length.to!int;
    E[] t;
    t.length = n-1;
    int e = 1, last, ti;
    void add_node(int i) {
        t[ti++] = E(1, ++e);
        auto o = e;
        foreach (_; 0..i-last-1) {
            t[ti++] = E(e, ++e);
        }
        auto ee = e;
        foreach (_; 0..last) {
            t[ti++] = E(ee, ++e);
        }
    }
    foreach (int i; 0..n/2) {
        if (s[i] == '0' && s[i-1] == '1') {
            add_node(i);
        } else {
            if (i == 0 || s[i-1] == '0') last = i;
        }
    }
    if (s[n/2-1] == '1') add_node(n/2);
    while (e < n) {
        t[ti++] = E(1, ++e);
    }

    foreach (x; t) {
        writefln("%d %d", x[0], x[1]);
    }
}

