        for(int i = k; i ; --i) {
            a[i] = 1LL << (i - 1);
            printf("%lld%c", a[i], i == 1LL ? '\n' : ' ');
        }
        for(int i = 1; i <= n; ++i){
            if(even) putchar('L'), x[i]++;
            dfs(x[i], y[i], k);
            putchar('\n');
        }
    }
