def error_print(*args):
    print(*args, file=sys.stderr)


def mt(f):
    import time

    def wrap(*args, **kwargs):
        s = time.time()
        ret = f(*args, **kwargs)
        e = time.time()

        error_print(e - s, 'sec')
        return ret

    return wrap


@mt
def slv(S):
    N = len(S)
    if S[N-1] == '1':
        print(-1)
        return -1

    if S[0] != '1':
        print(-1)
        return -1

    if S[N-2] != '1':
        print(-1)
        return -1


    for i in range(N//2):
        if S[i] != S[N-2-i]:
            print(-1)
            return -1

    comp = []
    g = defaultdict(set)

    l = [1]
    r = [j for j in range(2, N+1)]
    u = l.pop()
    v = r.pop()
    g[u].add(v)
    g[v].add(u)
    heapq.heappush(comp, (len(l), (u, l)))
    heapq.heappush(comp, (len(r), (v, r)))
    for i in range(2, N//2+1):
        if S[i-1] == '0':
            continue
        else:
            c = 0
            while c < i:
                c, (u, chs) = heapq.heappop(comp)
                if c < i:
                    for v in chs:
                        g[u].add(v)
                        g[v].add(u)

            l = chs[:i]
            v = l.pop()
            g[u].add(v)
            g[v].add(u)
            heapq.heappush(comp, (len(l), (v, l)))

            r = chs[i:]
            for v in r:
                g[u].add(v)
                g[v].add(u)
    while comp:
        _, (u, vs) = comp.pop()
        for v in vs:
            g[u].add(v)
            g[v].add(u)

    for i in range(1, N+1):
        for j in range(i+1, N+1):
            if j in g[i]:
                print(i, j)


