def slv(S):
    N = len(S)
    if S[N-1] == '1':
        print(-1)
        return -1

    if S[0] != '1':
        print(-1)
        return -1

    if S[N-2] != '1':
        print(-1)
        return -1


    for i in range(N//2):
        if S[i] != S[N-2-i]:
            print(-1)
            return -1

    comp = []
    e = []

    l = [1]
    r = [j for j in range(2, N+1)]
    u = l.pop()
    v = r.pop()
    e.append((u, v))
    heapq.heappush(comp, (len(l), (u, l)))
    heapq.heappush(comp, (len(r), (v, r)))
    for i in range(2, N//2+1):
        if S[i-1] == '0':
            continue
        else:
            c = 0
            while c < i:
                c, (u, chs) = heapq.heappop(comp)
                if c < i:
                    for v in chs:
                        e.append((u, v))

            l = chs[:i]
            if l:
                v = l.pop()
                e.append((u, v))
                heapq.heappush(comp, (len(l), (v, l)))

            r = chs[i:]
            if r:
                v = r.pop()
                e.append((u, v))
                heapq.heappush(comp, (len(r), (v, r)))

    while comp:
        _, (u, vs) = comp.pop()
        for v in vs:
            e.append((u, v))

    for u, v in e:
        print(u, v)



