use std::io::prelude::*;

fn input<T: std::str::FromStr>() -> T {
    let stdin = std::io::stdin();
    let token: String = stdin
        .lock()
        .bytes()
        .map(|c| c.unwrap() as char)
        .skip_while(|c| c.is_whitespace())
        .take_while(|c| !c.is_whitespace())
        .collect();
    token.parse().ok().unwrap()
}

fn with_stdout_lock<F: FnOnce(std::io::BufWriter<std::io::StdoutLock>)>(f: F) {
    let out = std::io::stdout();
    let w = std::io::BufWriter::new(out.lock());
    f(w);
}

fn main() {
    let s: Vec<char> = input::<String>().chars().collect();
    let n = s.len();

    let mut ok = s[0] == '1' && s[n - 1] == '0';
    for i in 0..n {
        let j = n - 2 - i;
        if i > j {
            break;
        }
        if s[i] != s[j] {
            ok = false;
            break;
        }
    }
    if !ok {
        println!("-1");
        return;
    }

    let mut ans = vec![];
    let mut zeros = vec![];
    let mut prev = n + 1;
    for i in 0..n {
        if i == n - 1 || s[i] == '1' {
            if prev <= n {
                ans.push((prev, i + 1));
                for &z in &zeros {
                    ans.push((i + 1, z));
                }
            }
            zeros.clear();
            prev = i + 1;
        } else {
            zeros.push(i + 1);
        }
    }

    with_stdout_lock(|mut w| {
        for (u, v) in ans {
            writeln!(w, "{} {}", u, v).unwrap();
        }
    });
}

#[allow(unused_macros)]
macro_rules! input {
    (source = $s:expr, $($r:tt)*) => {
        let mut iter = $s.split_whitespace();
        let mut next = || { iter.next().unwrap() };
