fn solve() {
    let s: Vec<bool> = util::line().chars().map(|c| c == '1').collect();

    let n = s.len();

    if n == 2 {
        if s[0] && !s[1] {
            println!("1 2");
        } else {
            println!("-1");
        }
        return;
    }

    if !s[0] || s[n - 1] || !s[n - 2] || (1..n / 2).any(|i| s[i] != s[n - 2 - i]) {
        println!("-1");
        return;
    }

    let mut par = vec![0; n];
    let mut f = 1;

    let mut i = 1;
    while i < n / 2 {
        if s[i] {
            let l = i + 1;
            while i < n / 2 && s[i] {
                i += 1;
            }
            let r = i;

            let c = f;
            for _ in 0..l - 1 {
                f += 1;
                par[f] = c;
            }

            if l != r {
                for _ in l..r {
                    f += 1;
                    par[c] = f;
                }
                par[f] = 0;
            }
        } else {
            i += 1;
        }
    }

    for i in 1..n {
        println!("{} {}", i + 1, par[i] + 1);
    }
}

