struct Tree {
    id: usize,
    child: Vec<Tree>,
}

impl Tree {
    fn new(id: usize) -> Tree {
        Tree {
            id: id,
            child: Vec::new(),
        }
    }

    fn add_child(&mut self, mut sorted_child_nums: Vec<usize>) {
        assert!(self.child.is_empty());
        if sorted_child_nums.len() == 0 {
            return;
        }
        if sorted_child_nums.len() == 1 {
            for i in 0..sorted_child_nums[0] - 1 {
                self.child.push(Tree::new(self.id + i + 1));
            }
            return;
        }

        let max_child_num = sorted_child_nums.pop().unwrap();
        let second_child_num = sorted_child_nums[sorted_child_nums.len() - 1];

        self.child.push(Tree::new(self.id + 1));
        self.child[0].add_child(sorted_child_nums);

        for i in second_child_num..max_child_num {
            self.child.push(Tree::new(self.id + i));
        }
    }

    fn print(&self) {
        for ref child in self.child.iter() {
            println!("{0} {1}", self.id + 1, child.id + 1);
            child.print();
        }
    }
}

fn main() {
    let s = read::<String>()
        .chars()
        .map(|x| x.to_digit(10).unwrap())
        .collect::<Vec<u32>>();
    if !check(&s) {
        println!("-1");
        return;
    }
    let n = s.len();

    let mut odd_elements = Vec::new();
    let mut even_elements = Vec::new();

    for i in 1..n / 2 {
        let num = i + 1;
        if s[i] == 1 && num >= 1 {
            if num % 2 == 1 {
                odd_elements.push(num);
            } else {
                even_elements.push(num);
            }
        }
    }
    // println!("even elements {:?}", &even_elements);
    // println!("odd elements {:?}", &odd_elements);

    // make 0-indexed tree.
    let mut root = Tree::new(0);
    let mut idx_for_odd_max = 0;
    if !odd_elements.is_empty() {
        idx_for_odd_max = if let Some(&x) = odd_elements.iter().max() {
            x
        } else {
            1
        };
        let mut odd_root = Tree::new(1);
        odd_root.add_child(odd_elements);
        root.child.push(odd_root);
    }

    let mut idx_for_even_max = idx_for_odd_max;
    if !even_elements.is_empty() {
        idx_for_even_max = if let Some(&x) = even_elements.iter().max() {
            x + idx_for_odd_max
        } else {
            1 + idx_for_odd_max
        };
        let mut even_root = Tree::new(idx_for_odd_max + 1);
        even_root.add_child(even_elements);
        root.child.push(even_root);
    }

    for i in idx_for_even_max + 1..n {
        root.child.push(Tree::new(i));
    }

