fn solve(s: &str) {
    let s = s.split_whitespace().next().unwrap();
    let s: Vec<bool> = s
        .chars()
        .map(|x| x.to_digit(10).unwrap())
        .map(|x| x != 0)
        .collect();
    let n = s.len();
    if !s[0] || s[n - 1] {
        println!("{}", -1);
        return;
    }
    let mut nexts = vec![vec![]; n];
    nexts[0].push(1);
    let mut cur = 1;
    for i in 1..(s.len() - 1) {
        if s[i] != s[n - i - 2] {
            println!("{}", -1);
            return;
        }
        nexts[cur].push(i + 1);
        if s[i] {
            cur += 1;
        }
    }
    let mut count = 0;
    for i in 0..n {
        for &j in nexts[i].iter() {
            println!("{} {}", i + 1, j + 1);
            count += 1;
        }
    }
    assert_eq!(count, n - 1)
}

