    }
    if s[1] == '0' || s[n - 1] == '0' {
        ok = false;
    }
    for i in 1 .. n {
        if s[i] != s[n - i] {
            ok = false;
        }
    }
    if !ok {
        puts!("-1\n");
        return;
    }
    let mut edges = vec![];
    let mut pool = vec![];
    for i in 1 .. n + 1 {
        if s[i] == '1' {
            for p in pool.drain(..) {
                edges.push((p, i));
            }
        }
        pool.push(i);
    }
    for p in pool {
        if p != n {
            edges.push((p, n));
        }
    }
    for (x, y) in edges {
        puts!("{} {}\n", x, y);
    }
}

