use std::cmp;
use std::collections::BTreeSet;

fn main() {
    input!(s: chars);
    let n = s.len();
    let s = s.iter().map(|&c| c == '1').collect::<Vec<_>>();
    if !s[0] || s[n - 1] {
        println!("-1");
        return;
    }

    let mut tree = vec![vec![]; n];
    let mut cur = 0;
    let mut cur_size = 1;

    for i in 0..(n - 1) {
        let one = i + 1;
        let other = n - one;
        if s[one - 1] != s[other - 1] {
            println!("-1");
            return;
        }
        if !s[i] {
            continue;
        }

        let have_to_add = one - cur_size + 1;
        for _ in 0..have_to_add {
            if cur_size == n {
                println!("-1");
                return;
            }
            let v = cur_size;
            tree[cur].push(v);
            tree[v].push(cur);
            cur_size += 1;
        }
        cur = cur_size - 1;
    }

    let mut set = BTreeSet::new();
    for from in 0..n {
        for &to in tree[from].iter() {
            let (a, b) = (cmp::min(from, to), cmp::max(from, to));
            set.insert((a, b));
        }
    }

    assert_eq!(set.len(), n - 1);
    for &(a, b) in set.iter() {
        println!("{} {}", a + 1, b + 1);
    }
}

pub trait Readable {
    type Output;
    fn words_count() -> usize;
    fn read_words(words: &[&str]) -> Result<Self::Output, String>;
}
#[macro_export]
macro_rules! readable {
    ( $ t : ty , |$ words : ident | $ read_words : expr ) => {
        readable!($t, 1, |$words| $read_words);
    };
    ( $ t : ty , $ words_count : expr , |$ words : ident | $ read_words : expr ) => {
        impl Readable for $t {
            type Output = $t;
            fn words_count() -> usize {
                $words_count
            }
            fn read_words($words: &[&str]) -> Result<$t, String> {
                Ok($read_words)
            }
        }
    };
}
