use std::iter;

fn is_palin(s: &[bool]) -> bool {
    s.iter().zip(s.iter().rev()).all(|(a, b)| a == b)
}

// Uses s.len() new nodes.
fn construct(start: u32, decomposable: &[bool], ans: &mut Vec<(u32, u32)>) {
    assert!(decomposable.len() >= 1);

    ans.push((start, start + 1));
    let (&last, first) = decomposable.split_last().unwrap();
    if first.is_empty() {
        return;
    }


    if last {
        construct(start + 1, first, ans);
    } else {
        let (l, r) = split(first);
        construct(start + 1, l, ans);
        let next = start + 1 + l.len() as u32 + 1;
        for i in (next..).take(r.len()) {
            ans.push((next - 1, i));
        }
    }
}

fn split(seq: &[bool]) -> (&[bool], &[bool]) {
    let i = (0..seq.len()-1).rev().find(|&i| seq[i]).unwrap();
    (&seq[..i+1], &seq[i+1..])
}


fn main() {
    read!(s = String);
    let s: Vec<bool> = iter::once(false)
        .chain(s.chars().map(|c| c == '1'))
        .collect();
    if !s[1] || !is_palin(&s) {
        println!("-1");
        return;
    }

    let end = (s.len()+1) / 2;
    let bs: Vec<bool> = s[1..end].iter().cloned()
        .chain(vec![false; s.len() - end - 1]).collect();
    let mut ans = Vec::new();
    construct(1, &bs, &mut ans);
    for (a, b) in ans.into_iter() {
        println!("{} {}", a, b);
    }
}

