fn solve(s: String) -> Option<Vec<(usize, usize)>> {

    let cvec = s.chars().collect::<Vec<_>>();
    let n = cvec.len();

    if cvec[0] != '1' { return None }
    if cvec[n-1] != '0' { return None }

    let mut parent = n;
    let mut ans = Vec::new();

    for i in (0..(n-1)).rev() {
        if cvec[i] != cvec[n-i-2] { return None }

        ans.push((parent, i+1));
        if cvec[i] == '1' {
            parent = i+1;
        }
    }

    return Some(ans)
}

