fn solve(s: Vec<i32>) -> Option<Vec<(usize, usize)>> {
    let n = s.len();
    if s[n-1] == 1 {
        return None;
    }
    if s[0] == 0 {
        return None;
    }
    for i in 0..n-1 {
        if s[i] != s[n-2-i] {
            return None;
        }
    }

    let mut edges = vec![];


    let mut last_one = 0;
    for v in 1..n-1 {
        if s[v] == 1 {
            let cnt = v - last_one;
            for w in last_one..v {
                edges.push((w, v));
            }
            last_one = v;
        }
    }
    assert_eq!(last_one, n-2);
    edges.push((last_one, n-1));
    assert_eq!(edges.len(), n-1);

    Some(edges)
}

fn main() {
    input! {
        s: chars
    };
    let s = s.into_iter().map(|c| ifv!(c == '0', 0, 1)).collect::<Vec<_>>();
    let edges = solve(s);
    match edges {
        Some(e) => {
            for (u, v) in e {
                println!("{} {}", u+1, v+1);
            }
        },
        None => {
            println!("-1");
        }
    }
}

