use std::io::{stdin, Read};

#[allow(unused_macros)]
macro_rules! parse {
    ($it: ident ) => {};
    ($it: ident, ) => {};
    ($it: ident, $var:ident : $t:tt $($r:tt)*) => {
        let $var = parse_val!($it, $t);
        parse!($it $($r)*);
    };
    ($it: ident, mut $var:ident : $t:tt $($r:tt)*) => {
        let mut $var = parse_val!($it, $t);
        parse!($it $($r)*);
    };
}

#[allow(unused_macros)]
macro_rules! parse_val {
    ($it: ident, [$t:tt; $len:expr]) => {
        (0..$len).map(|_| parse_val!($it, $t)).collect::<Vec<_>>();
    };
    ($it: ident, ($($t: ty),*)) => {
        ($(parse_val!($it, $t)),*)
    };
    ($it: ident, $t: ty) => {
        $it.next().unwrap().parse::<$t>().unwrap()
    };
}

fn solve(s: &str) {
    let s = s.split_whitespace().next().unwrap();
    let s: Vec<bool> = s
        .chars()
        .map(|x| x.to_digit(10).unwrap())
        .map(|x| x != 0)
        .collect();
    let n = s.len();
    if !s[0] || s[n - 1] {
        println!("{}", -1);
        return;
    }
    let mut nexts = vec![vec![]; n];
    nexts[0].push(1);
    let mut cur = 1;
    for i in 1..(s.len() - 1) {
        if s[i] != s[n - i - 2] {
            println!("{}", -1);
            return;
        }
        nexts[cur].push(i + 1);
        if s[i] && i <= (n / 2 - 1) {
            cur += 1;
        }
    }
    for i in 0..n {
        for &j in nexts[i].iter() {
            println!("{} {}", i + 1, j + 1);
        }
    }
}

fn main() {
    let mut s = String::new();
    stdin().read_to_string(&mut s).unwrap();
    solve(&s);
}

