fn main() {
    let cin = stdin();
    let mut scan = Scanner::new(cin.lock());
    let s = scan.chars();
    let n = s.len();
    let mut is_ok = true;
    if s[0] != '1' || s[n-1] != '0' {
        is_ok = false;
    }
    for i in 0..n {
        if i >= n-2-i {break;}
        if s[i] != s[n-2-i] {
            is_ok = false;
        }
    }
    if !is_ok {
        println!("-1");
        return;
    }
    let mut leaf = vec![];
    let mut edge = vec![];
    for i in 0..n {
        let mut c = s[i];
        if i == n-1 {c = '1';}
        if c == '0' {
            leaf.push(i);
        } else {
            for &v in &leaf {
                edge.push((v, i));
            }
            leaf = vec![i];
        }
    }
    for &(p, q) in &edge {
        println!("{} {}", p+1, q+1);
    }
}

