#[fastout]
fn main() {
    input! {
        mut s:Bytes,
    }
    let n = s.len();
    if s[0] == b'0' || s[n - 1] == b'1' {
        println!("-1");
        return;
    }
    for i in (0..).take_while(|&i| i < n - 2 - i) {
        if s[i] != s[n - 2 - i] {
            println!("-1");
            return;
        }
    }
    let s = s
        .iter()
        .map(|&b| b as usize - b'0' as usize)
        .collect::<Vec<usize>>();
    println!("{} {}", n - 1, n);
    let mut p = n - 2;
    for v in (0..n - 2).rev() {
        println!("{} {}", v + 1, p + 1);
        if s[v] == 1 {
            p = v;
        }
    }
}

