use std::iter;

fn is_palin(s: &[bool]) -> bool {
    s.iter().zip(s.iter().rev()).all(|(a, b)| a == b)
}

// Uses s.len() new nodes.
fn construct(start: u32, decomposable: &[bool]) -> Vec<(u32, u32)> {
    assert!(decomposable.len() >= 1);
    if decomposable.len() == 1 {
        vec![(start, start + 1)]
    } else if *decomposable.last().unwrap() {
        let mut res = construct(start + 1, &decomposable[..decomposable.len()-1]);
        res.push((start, start + 1));
        res
    } else {
        dbg!(&decomposable);
        let (l, r) = split(decomposable);
        let mut res = construct(start + 1, l);
        res.append(&mut parallel(start + l.len() as u32 + 1, r.len() as u32 - 1));
        res.push((start, start + 1));
        res
    }
}

fn parallel(start: u32, n: u32) -> Vec<(u32, u32)> {
    (start+1..).take(n as usize).map(|i| (start, i)).collect()
}

fn split(seq: &[bool]) -> (&[bool], &[bool]) {
    let i = (0..seq.len()-1).rev().find(|&i| seq[i]).unwrap();
    (&seq[..i+1], &seq[i+1..])
}


fn main() {
    read!(s = String);
    let s: Vec<bool> = iter::once(false)
        .chain(s.chars().map(|c| c == '1'))
        .collect();
    if !s[1] || !is_palin(&s) {
        println!("-1");
        return;
    }

    let end = (s.len()+1) / 2;
    let bs: Vec<bool> = s[1..end].iter().cloned()
        .chain(vec![false; s.len() - end - 1]).collect();
    for (a, b) in construct(1, &bs).into_iter() {
        println!("{} {}", a, b);
    }
}

#[allow(unused_macros)]
macro_rules! input {
    (source = $s:expr, $($r:tt)*) => {
        let mut iter = $s.split_whitespace();
        let mut next = || { iter.next().unwrap() };
        input_inner!{next, $($r)*}
    };
    ($($r:tt)*) => {
        let stdin = std::io::stdin();
        let mut bytes = std::io::Read::bytes(std::io::BufReader::new(stdin.lock()));
        let mut next = move || -> String{
            bytes
                .by_ref()
                .map(|r|r.unwrap() as char)
                .skip_while(|c|c.is_whitespace())
                .take_while(|c|!c.is_whitespace())
                .collect()
        };
        input_inner!{next, $($r)*}
    };
}

#[allow(unused_macros)]
macro_rules! input_inner {
    ($next:expr) => {};
    ($next:expr, ) => {};

    ($next:expr, $var:ident : $t:tt $($r:tt)*) => {
        let $var = read_value!($next, $t);
        input_inner!{$next $($r)*}
    };
}

#[allow(unused_macros)]
macro_rules! read_value {
    ($next:expr, ( $($t:tt),* )) => {
        ( $(read_value!($next, $t)),* )
    };

    ($next:expr, [ $t:tt ; $len:expr ]) => {
        (0..$len).map(|_| read_value!($next, $t)).collect::<Vec<_>>()
    };

    ($next:expr, chars) => {
        read_value!($next, String).chars().collect::<Vec<char>>()
    };

    ($next:expr, usize1) => {
        read_value!($next, usize) - 1
    };

    ($next:expr, $t:ty) => {
        $next().parse::<$t>().expect("Parse error")
    };
}

#[allow(unused_macros)]
macro_rules! debug {
    ($($a:expr),*) => {
        #[cfg(debug_assertions)]
        writeln!(&mut std::io::stderr(), concat!("[DEBUG] ", $(stringify!($a), "={:?} "),*), $($a),*);
    }
}

