use std::cmp::{min, max};

#[allow(unused_imports)]
use std::io::Write;

fn main() {
    input!{
      s: chars,
    }
    let n = s.len();
    if s[0] != '1' {
        return println!("{}", -1);
    }
    if s[n-1] == '1' {
        return println!("{}", -1);
    }

    for i in 1..n+1 {
        if !(n >= i+1) {
            break;
        }
        let j = n-i;
        if s[i-1] != s[j-1] {
            return println!("{}", -1);
        }
    }

    let mut leafs = vec![0];
    for i in 1..n-1 {
        if s[i] == '1' {
            for &l in leafs.iter() {
                println!("{} {}", l+1, i+1);
            }
            leafs = vec![i];
        } else {
            leafs.push(i);
        }
    }
    println!("{} {}", n-1, n);
}

use std::cmp::*;
use std::io::*;

fn main() {
    let mut s: String = String::new();
    std::io::stdin().read_to_string(&mut s).ok();
    let mut itr = s.trim().split_whitespace();
    let s: Vec<char> = itr.next().unwrap().chars().collect();
    let n = s.len();

    //
    if s[0] == '0' || s[n - 1] == '1' {
        println!("-1");
        return;
    }

    let mut line = 0;
    let mut ok = true;
    for i in 0..n / 2 {
        if s[i] == '1' && s[n - i - 2] == '0' {
            ok = false;
        }
        if s[i] == '1' && s[i + 1] == '0' {
            line = i;
            break;
        }
    }

    if ok {
        //
        let mut out = Vec::new();
        for i in 0..=line {
            writeln!(out, "{} {}", i + 1, i + 2).ok();
        }
        // line+1から他
        for i in line + 2..n {
            writeln!(out, "{} {}", line + 2, i + 1).ok();
        }
        stdout().write_all(&out).unwrap();
    } else {
        println!("-1");
    }
}
